import { type Bullet } from 'type/Bullet'
import { type Enemy } from 'type/Enemy'
import { type User } from 'type/User'
import { DrawUtil } from 'utils/drawUtil'

import { WARNING_POSITION_Z } from './game'
import { playSound } from './sound'

export class GameDraw {
  // View関連
  webcamElement: HTMLVideoElement
  canvasElement: HTMLCanvasElement
  shootingCanvasElement: HTMLCanvasElement
  ctx: CanvasRenderingContext2D
  shootingCtx: CanvasRenderingContext2D
  effectDivElement: HTMLDivElement

  // ゲーム関連
  user: User
  bulletList: Bullet[] = []
  enemyList: Enemy[] = []
  stars: Array<{ x: number; y: number; speed: number }> = []

  // Util関連
  shootingCtxDrawUtil: DrawUtil

  constructor(
    webcamElement: HTMLVideoElement,
    canvasElement: HTMLCanvasElement,
    shootingCanvasElement: HTMLCanvasElement,
    ctx: CanvasRenderingContext2D,
    shootingCtx: CanvasRenderingContext2D,
    effectDivElement: HTMLDivElement,
    user: User,
    bulletList: Bullet[],
    enemyList: Enemy[],
  ) {
    // View関連
    this.webcamElement = webcamElement
    this.canvasElement = canvasElement
    this.shootingCanvasElement = shootingCanvasElement
    this.ctx = ctx
    this.shootingCtx = shootingCtx
    this.effectDivElement = effectDivElement

    // ゲーム関連
    this.user = user
    this.bulletList = bulletList
    this.enemyList = enemyList

    // Util関連
    this.shootingCtxDrawUtil = new DrawUtil(
      this.shootingCtx,
      this.shootingCanvasElement,
      this.webcamElement,
    )
  }

  drawInit() {
    // canvasをクリア
    this.ctx.clearRect(0, 0, this.canvasElement.width, this.canvasElement.height)

    // シューティングCanvasをクリア
    this.shootingCtx.clearRect(
      0,
      0,
      this.shootingCanvasElement.width,
      this.shootingCanvasElement.height,
    )

    // ctxに対してシューティングエリアの背景色を黒に設定
    this.ctx.fillStyle = 'black'
    this.ctx.fillRect(0, 0, this.shootingCanvasElement.width, this.shootingCanvasElement.height)

    this.drawStars()
  }

  drawPrologue(): void {
    const textColor = 'black'

    // 白の背景の四角を描画
    const margin = 100
    const padding = 20
    this.shootingCtx.beginPath()
    // 半透明
    this.shootingCtx.fillStyle = 'rgba(255, 255, 255, 0.8)'
    this.shootingCtx.fillRect(
      margin,
      margin,
      this.shootingCanvasElement.width - margin * 2,
      this.shootingCanvasElement.height - margin * 2,
    )
    this.shootingCtx.closePath()

    // 四角の内部に枠線を描画
    const borderPadding = 5
    this.shootingCtx.beginPath()
    this.shootingCtx.lineWidth = 5
    this.shootingCtx.strokeStyle = 'black'
    this.shootingCtx.strokeRect(
      margin + borderPadding,
      margin + borderPadding,
      this.shootingCanvasElement.width - margin * 2 - borderPadding * 2,
      this.shootingCanvasElement.height - margin * 2 - borderPadding * 2,
    )
    this.shootingCtx.closePath()

    const episodeText = `Episode ${this.user.gameEpisode}`
    const titleText = this.user.getEpisodeTitle()

    // 左上にエピソードのテキストを表示
    this.shootingCtx.fillStyle = textColor
    this.shootingCtx.font = '30px Arial'
    this.shootingCtx.fillText(episodeText, margin + padding, margin + padding + 30)

    // 右下にタイトルのテキストを表示
    this.shootingCtx.font = '80px Arial'
    const titleTextWidth = this.shootingCtx.measureText(titleText).width
    this.shootingCtx.fillStyle = textColor
    this.shootingCtx.fillText(
      titleText,
      this.shootingCanvasElement.width - titleTextWidth - padding - margin - 10,
      this.shootingCanvasElement.height - padding - margin - 10,
    )
  }

  drawEpilogue(): void {
    console.log('drawEpilogue')

    const epilogueText = `Episode ${this.user.gameEpisode} Mission Completed`
    // 画面中央にエピローグのテキストを表示
    this.shootingCtx.font = '30px Arial'
    const epilogueTextWidth = this.shootingCtx.measureText(epilogueText).width

    this.shootingCtx.save()
    this.shootingCtx.fillStyle = 'white'
    this.shootingCtx.fillText(
      epilogueText,
      this.shootingCanvasElement.width / 2 - epilogueTextWidth / 2,
      this.shootingCanvasElement.height / 2,
    )
    this.shootingCtx.restore()
  }

  drawInitPlaying() {
    // プロローグのglobeエフェクトを削除
  }

  drawDistanceText(): void {
    // 敵のZ座標を表示

    this.enemyList.forEach((enemy) => {
      if (enemy.threeObject == null) return

      // Z座標を小数点第１位まで表示
      const distance = Math.floor(enemy.z * 10) / 10

      let color = 'lightgray'
      if (distance < WARNING_POSITION_Z) {
        color = 'orangered'
      }

      this.shootingCtx.font = '14px Arial'
      this.shootingCtx.fillStyle = color
      this.shootingCtx.fillText(`distance:${distance}`, enemy.x + 50, enemy.y + 50)

      // テキストの下に赤い線を引く
      this.shootingCtx.beginPath()
      this.shootingCtx.moveTo(enemy.x, enemy.y)
      this.shootingCtx.lineTo(enemy.x + 50, enemy.y + 55)
      this.shootingCtx.strokeStyle = color
      this.shootingCtx.stroke()

      this.shootingCtx.moveTo(enemy.x + 50, enemy.y + 55)
      this.shootingCtx.lineTo(enemy.x + 100, enemy.y + 55)
      this.shootingCtx.strokeStyle = color
      this.shootingCtx.stroke()
      this.shootingCtx.closePath()
    })
  }

  drawWarningText(): void {
    if (this.enemyList.length === 0) return

    // 一番Z座標が近い敵を取得
    const nearestEnemy = this.enemyList.reduce((prev, current) =>
      prev.z < current.z ? prev : current,
    )

    if (nearestEnemy != null && Math.floor(nearestEnemy.z) <= WARNING_POSITION_Z) {
      // Z座標が5の倍数、かつ10より大きい場合は警告を表示
      if (Math.floor(nearestEnemy.z) % 5 !== 0 && Math.floor(nearestEnemy.z) > 10) return

      // 警告音を鳴らす
      playSound('warning')

      let color = 'orange'
      if (Math.floor(nearestEnemy.z) <= 10) {
        color = 'red'
      }

      // 警告テキストの幅を取得する
      const warningText = 'Warning'
      const warningTextHeight = 18
      const marginTop = 40
      const paddingX = 40
      const paddingY = 4

      const font = '18px Arial'

      this.shootingCtx.save()
      this.shootingCtx.font = font
      const warningTextWidth = this.shootingCtx.measureText(warningText).width
      this.shootingCtx.restore()

      // 警告テキストを赤い四角の線で囲む
      this.shootingCtx.save()
      this.shootingCtx.beginPath()
      this.shootingCtx.rect(
        this.shootingCanvasElement.width / 2 - warningTextWidth / 2 - paddingX,
        marginTop,
        warningTextWidth + paddingX * 2,
        warningTextHeight + paddingY * 2,
      )
      // 白の透明で塗りつぶす
      this.shootingCtx.fillStyle = 'rgba(255, 255, 255, 0.2)'
      this.shootingCtx.fill()
      // 枠線を引く
      this.shootingCtx.strokeStyle = color
      // 線の太さを設定
      this.shootingCtx.lineWidth = 2
      // 枠線をぼかす
      this.shootingCtx.shadowColor = color
      this.shootingCtx.shadowBlur = 2
      this.shootingCtx.shadowOffsetX = 0
      this.shootingCtx.shadowOffsetY = 0

      this.shootingCtx.stroke()
      this.shootingCtx.closePath()
      this.shootingCtx.restore()

      // 警告テキストを画面中央に表示
      this.shootingCtx.save()
      this.shootingCtx.beginPath()
      this.shootingCtx.font = font
      this.shootingCtx.fillStyle = color
      this.shootingCtx.fillText(
        warningText,
        this.shootingCanvasElement.width / 2 - warningTextWidth / 2,
        warningTextHeight + marginTop,
      )
      this.shootingCtx.closePath()
      this.shootingCtx.restore()
    }
  }

  drawGameStart(callback: ()=>void): void {
    // 画面中央にロゴテキスト（Star Hands） を表示
    const logoText = 'Star Hands'
    this.shootingCtx.font = 'bold 40px copperplate'
    const logoTextWidth = this.shootingCtx.measureText(logoText).width

    this.shootingCtx.save()
    this.shootingCtx.fillStyle = 'white'
    this.shootingCtx.fillText(
      logoText,
      this.shootingCanvasElement.width / 2 - logoTextWidth / 2,
      100,
    )
    this.shootingCtx.restore()

    // 画面中央に横に長い丸のボタンを表示
    const startButtonWidth = 200
    const startButtonHeight = 50
    const startButtonX = this.shootingCanvasElement.width / 2 - startButtonWidth / 2
    const startButtonY = this.shootingCanvasElement.height / 2

    this.shootingCtx.save()
    this.shootingCtx.beginPath()
    this.shootingCtx.lineWidth = 5
    this.shootingCtx.strokeStyle = 'white'
    this.shootingCtx.fillStyle = 'rgba(255, 255, 255, 0.5)'
    this.shootingCtx.arc(
      this.shootingCanvasElement.width / 2,
      this.shootingCanvasElement.height / 2,
      50,
      0,
      Math.PI * 2,
    )
    this.shootingCtx.fill()
    this.shootingCtx.stroke()
    this.shootingCtx.closePath()

    // STARTボタンのテキストを表示
    const startButtonText = 'START'
    this.shootingCtx.font = 'bold 24px din'
    const startButtonTextWidth = this.shootingCtx.measureText(startButtonText).width
    this.shootingCtx.fillStyle = 'black'
    this.shootingCtx.fillText(
      startButtonText,
      this.shootingCanvasElement.width / 2 - startButtonTextWidth / 2,
      this.shootingCanvasElement.height / 2 + 10,
    )
    this.shootingCtx.restore()

    // ボタンのイベント処理を追加
    this.shootingCanvasElement.addEventListener('click', (e) => {
      const rect = this.shootingCanvasElement.getBoundingClientRect()
      const x = e.clientX - rect.left
      const y = e.clientY - rect.top

      // ボタンの範囲内をクリックしたらゲームスタート
      if (
        x > startButtonX &&
        x < startButtonX + startButtonWidth &&
        y > startButtonY - startButtonHeight &&
        y < startButtonY + startButtonHeight
      ) {
        callback()
      }
    })
  }

  drawGameOver(): void {
    const gameOverText = 'Game Over'

    this.shootingCtx.font = '30px Arial'
    this.shootingCtx.fillStyle = 'red'

    const textWidth = this.shootingCtx.measureText(gameOverText).width

    // ゲームオーバーのテキストを表示
    if (this.shootingCtx == null || this.shootingCanvasElement == null) return
    this.shootingCtx.fillText(
      gameOverText,
      this.shootingCanvasElement.width / 2 - textWidth / 2,
      this.shootingCanvasElement.height / 2,
    )

    // 5秒後にresultに遷移
    setTimeout(() => {
      this.user.gameScene = 'result'
    }, 5000)
  }

  drawGameResult(): void {}

  drawUser(): void {
    // 画面左下に平行四辺形の背景を描画
    const userBackgroundWidth = 200
    const userBackgroundHeight = 40
    const userBackgroundMargin = 20
    const userBackgroundX = userBackgroundMargin
    const userBackgroundY =
      this.shootingCanvasElement.height - userBackgroundHeight - userBackgroundMargin

    const userGradient = this.shootingCtx.createLinearGradient(
      userBackgroundX,
      userBackgroundY,
      userBackgroundX,
      userBackgroundY + userBackgroundHeight,
    )
    userGradient.addColorStop(0, 'rgba(0, 0, 0, 0.5)')
    userGradient.addColorStop(1, 'rgba(255, 255, 255, 0.5)')

    this.shootingCtx.beginPath()
    this.shootingCtx.fillStyle = userGradient
    this.shootingCtx.moveTo(userBackgroundX, userBackgroundY)
    this.shootingCtx.lineTo(
      userBackgroundX + userBackgroundWidth - userBackgroundMargin,
      userBackgroundY,
    )
    this.shootingCtx.lineTo(
      userBackgroundX + userBackgroundWidth,
      userBackgroundY + userBackgroundHeight,
    )
    this.shootingCtx.lineTo(
      userBackgroundX + userBackgroundMargin,
      userBackgroundY + userBackgroundHeight,
    )
    this.shootingCtx.closePath()
    this.shootingCtx.fill()

    // スタミナを画面左下に横長の四角のバーの数で表示
    const barWidth = 30 // 各バーの幅
    const barHeight = 10 // 各バーの高さ
    const barPadding = 1 // 各バーの間のパディング
    const barMarginLeft = 5 // バーの左のマージン
    const barMarginBotton = 5 // バーの下のマージン
    const maxStamina = this.user.getMaxStamina()
    const staminaX = userBackgroundX + userBackgroundMargin + barMarginLeft
    const staminaY = userBackgroundY + userBackgroundHeight - barHeight - barMarginBotton

    this.shootingCtx.save()
    for (let i = 0; i < maxStamina; i++) {
      const x = staminaX + i * (barWidth + barPadding)
      this.shootingCtx.beginPath()
      this.shootingCtx.globalAlpha = 0.5
      this.shootingCtx.fillStyle = i < this.user.stamina ? 'deeppink' : 'white' // スタミナがある部分はピンク、ない部分は白
      this.shootingCtx.fillRect(x, staminaY, barWidth, barHeight)
      this.shootingCtx.lineWidth = 1
      this.shootingCtx.globalAlpha = 1
      this.shootingCtx.strokeStyle = 'white'
      this.shootingCtx.strokeRect(x, staminaY, barWidth, barHeight)
      this.shootingCtx.closePath()
    }
    this.shootingCtx.restore()

    // テキスト表示
    const staminaText = `Life`
    this.shootingCtx.save()
    this.shootingCtx.beginPath()
    this.shootingCtx.font = '12px Arial'
    this.shootingCtx.fillStyle = 'yellow'
    this.shootingCtx.fillText(staminaText, staminaX + 2, staminaY - 6)
    this.shootingCtx.closePath()
    this.shootingCtx.restore()

    // 画面右下に武器を表示するために平行四辺形を描画
    const weaponBackgroundWidth = 200
    const weaponBackgroundHeight = 40
    const weaponBackgroundMargin = 20
    const weaponBackgroundX =
      this.shootingCanvasElement.width - weaponBackgroundWidth - weaponBackgroundMargin
    const weaponBackgroundY =
      this.shootingCanvasElement.height - weaponBackgroundHeight - weaponBackgroundMargin

    this.shootingCtx.beginPath()
    // 背景色は白と黒のグラテーションを半透明にする
    const weaponGradient = this.shootingCtx.createLinearGradient(
      weaponBackgroundX,
      weaponBackgroundY,
      weaponBackgroundX,
      weaponBackgroundY + weaponBackgroundHeight,
    )
    weaponGradient.addColorStop(0, 'rgba(0, 0, 0, 0.5)')
    weaponGradient.addColorStop(1, 'rgba(255, 255, 255, 0.5)')

    this.shootingCtx.fillStyle = weaponGradient
    this.shootingCtx.moveTo(weaponBackgroundX + weaponBackgroundMargin, weaponBackgroundY)
    this.shootingCtx.lineTo(weaponBackgroundX + weaponBackgroundWidth, weaponBackgroundY)
    this.shootingCtx.lineTo(
      weaponBackgroundX + weaponBackgroundWidth - weaponBackgroundMargin,
      weaponBackgroundY + weaponBackgroundHeight,
    )
    this.shootingCtx.lineTo(weaponBackgroundX, weaponBackgroundY + weaponBackgroundHeight)
    this.shootingCtx.closePath()
    this.shootingCtx.fill()

    // チャージパワーを画面右下に横長の四角のバーの数で表示
    const chargePowerWidth = weaponBackgroundWidth - weaponBackgroundMargin * 2
    const chargePowerHeight = 12
    const chargePowerMarginBottom = 5
    const chargePowerX = weaponBackgroundX + weaponBackgroundMargin
    const chargePowerY =
      weaponBackgroundY + weaponBackgroundHeight - chargePowerHeight - chargePowerMarginBottom

    this.shootingCtx.beginPath()
    this.shootingCtx.fillStyle = 'white'
    this.shootingCtx.fillRect(chargePowerX, chargePowerY, chargePowerWidth, chargePowerHeight)
    this.shootingCtx.fillStyle = 'gold'
    this.shootingCtx.fillRect(
      chargePowerX,
      chargePowerY,
      chargePowerWidth * (this.user.chargePower / 5),
      chargePowerHeight,
    )
    this.shootingCtx.closePath()

    // 枠線を描画
    this.shootingCtx.beginPath()
    this.shootingCtx.lineWidth = 1
    this.shootingCtx.strokeStyle = 'green'
    this.shootingCtx.strokeRect(chargePowerX, chargePowerY, chargePowerWidth, chargePowerHeight)
    this.shootingCtx.closePath()

    // テキストを表示
    const chargePowerText = `beam charge`
    this.shootingCtx.beginPath()
    this.shootingCtx.font = '12px Arial'
    this.shootingCtx.fillStyle = 'lime'
    this.shootingCtx.fillText(chargePowerText, chargePowerX + 2, chargePowerY - 6)
    this.shootingCtx.closePath()

    // エピソードとステージを画面の右上に表示
    const episodeStageText = `Episode:${this.user.gameEpisode} Stage:${this.user.gameStage}`

    const marginRight = 20
    const marginTop = 30

    this.shootingCtx.beginPath()
    this.shootingCtx.font = '14px Arial'
    this.shootingCtx.fillStyle = 'green'
    const textWidth = this.shootingCtx.measureText(episodeStageText).width
    this.shootingCtx.fillText(
      episodeStageText,
      this.shootingCanvasElement.width - textWidth - marginRight,
      marginTop,
    )
    this.shootingCtx.closePath()
  }

  drawBallet(): void {
    if (this.bulletList.length > 0) {
      this.bulletList.forEach((bullet, index) => {
        if (this.shootingCtx == null || this.shootingCanvasElement == null) return

        // console.log('drawBullet', bullet)

        // 弾の描画
        bullet.y -= 1 // 弾を上に移動（奥に進むように見せるため）
        // Z座標を更新
        bullet.z += bullet.speed

        // Z座標が100を超えたら削除
        if (bullet.z > 100) {
          this.bulletList.splice(index, 1)
          return
        }

        // 弾の大きさを更新
        // Z座標が0の時にoriginalSize、100の時で0のサイズになるようにする
        bullet.size = bullet.originalSize - (bullet.originalSize / 100) * bullet.z

        if (bullet.type === 'beam') {
          // 青白いビームの光
          const gradient = this.shootingCtx.createRadialGradient(
            bullet.x,
            bullet.y,
            10,
            bullet.x,
            bullet.y,
            bullet.size * 2,
          )
          // 中心は白で中間は緑と黄色、外側は白の4色グラデーション
          gradient.addColorStop(0, 'rgba(255, 255, 255, 1)')
          gradient.addColorStop(0.5, 'rgba(255, 255, 255, 1)')
          gradient.addColorStop(0.7, 'rgba(0, 255, 0, 1)')
          gradient.addColorStop(0.9, 'rgba(255, 255, 0, 1)')
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)')
          this.shootingCtx.save()
          this.shootingCtx.beginPath()
          this.shootingCtx.arc(bullet.x, bullet.y, bullet.size, 0, Math.PI * 2)
          this.shootingCtx.fillStyle = gradient
          this.shootingCtx.shadowColor = 'yellow'
          this.shootingCtx.shadowBlur = 30
          this.shootingCtx.shadowOffsetX = 0
          this.shootingCtx.shadowOffsetY = 0
          this.shootingCtx.fill()
          this.shootingCtx.closePath()
          this.shootingCtx.restore()
        } else {
          // 白い光
          const gradient = this.shootingCtx.createRadialGradient(
            bullet.x,
            bullet.y,
            10,
            bullet.x,
            bullet.y,
            bullet.size * 2,
          )
          gradient.addColorStop(0, 'rgba(255, 255, 255, 1)')
          gradient.addColorStop(1, 'rgba(0, 0, 255, 0)')
          this.shootingCtx.beginPath()
          this.shootingCtx.arc(bullet.x, bullet.y, bullet.size, 0, Math.PI * 2)
          this.shootingCtx.fillStyle = gradient
          this.shootingCtx.fill()
          this.shootingCtx.closePath()
        }
      })
    }
  }

  drawStageReady(): void {}

  drawStageClear(): void {}

  drawStageNotClear(): void {}

  drawEffect(): void {}

  initStars(): void {
    for (let i = 0; i < 100; i++) {
      this.stars.push({
        x: Math.random() * this.shootingCanvasElement.width,
        y: Math.random() * this.shootingCanvasElement.height,
        speed: Math.random() * 1 + 0.1, // 星の移動速度をランダムに設定
      })
    }
  }

  drawStars(): void {
    // 星を描画
    this.stars.forEach((star) => {
      this.ctx.fillStyle = 'white'
      this.ctx.fillRect(star.x, star.y, 1, 1)

      // 星を移動
      star.x += star.speed

      // 星が画面外に出たら左に戻す
      if (star.x > this.canvasElement.width) {
        star.x = 0
      }
    })
  }
}
