import { type KnnEstimated } from '../type/KnnEstimated'

import type * as handPoseDetection from '@tensorflow-models/hand-pose-detection'

export const defaultTextFont = '24px sans-serif'

export class DrawUtil {
  ctx: CanvasRenderingContext2D
  canvasElement: HTMLCanvasElement
  webcamElement: HTMLVideoElement

  constructor(
    ctx: CanvasRenderingContext2D,
    canvasElement: HTMLCanvasElement,
    webcamElement: HTMLVideoElement,
  ) {
    this.ctx = ctx
    this.canvasElement = canvasElement
    this.webcamElement = webcamElement
  }

  mirrorX(x: number, width: number = 0): number {
    return this.canvasElement.width - x - width
  }

  // ウェブカメラの画像をCanvasに描画する関数
  drawWebCamToCanvas(): void {
    // キャンバスをクリア
    this.ctx.clearRect(0, 0, this.canvasElement.width, this.canvasElement.height)

    // キャンバスの水平反転を設定
    this.ctx.save() // 現在の状態を保存
    this.ctx.scale(-1, 1) // 水平反転
    this.ctx.translate(-this.canvasElement.width, 0) // 座標を移動して反転を適用

    this.ctx.drawImage(
      this.webcamElement,
      0,
      0,
      this.webcamElement.videoWidth,
      this.webcamElement.videoHeight,
    )

    this.ctx.restore() // 反転を元に戻す
  }

  // Canvasにテキストを描画する関数
  drawPoseNameToCanvas(hands: handPoseDetection.Hand[], estimateHandpose: KnnEstimated[]): void {
    if (hands == null || hands.length === 0) return

    hands.forEach((hand, index) => {
      const { keypoints } = hand
      const { name, probability } = estimateHandpose[index]

      // 手のキーポイントの2D座標（x, y）を名前（keypoint.name）から取得する関数
      const getKeypoint = (name: string) => keypoints.find((keypoint) => keypoint.name === name)

      const indexFingerTip = getKeypoint('index_finger_tip') // 人差し指の先端
      const middleFingerTip = getKeypoint('middle_finger_tip') // 中指の先端

      if (indexFingerTip && middleFingerTip) {
        // 人差し指と中指の中間点（X座標）
        const indexMiddleMidPointX = (indexFingerTip.x + middleFingerTip.x) / 2

        // 「どのポーズであるか」と「そのポーズである確率が1であるか」で表示を変える
        if (probability === 1) {
          this.drawText(indexMiddleMidPointX, indexFingerTip.y, name, 'maroon', '16px sans-serif')
        }
      }
    })
  }

  // テキストを描画する関数
  drawText(
    x: number,
    y: number,
    text: string,
    color: string,
    font: string = defaultTextFont,
  ): void {
    this.ctx.save() // 現在のキャンバス状態を保存
    this.ctx.font = font
    this.ctx.fillStyle = color
    this.ctx.fillText(text, this.mirrorX(x, this.ctx.measureText(text).width), y - 30)
    this.ctx.restore() // 元に戻す
  }

  drawOnlyHandToCanvas(hands: handPoseDetection.Hand[]): void {
    hands.forEach((hand) => {
      this.ctx.save() // 現在のキャンバス状態を保存

      // 手のキーポイントを取得
      const keypoints = hand.keypoints

      // 手のひらの部分を塗りつぶす
      this.ctx.beginPath()
      this.ctx.fillStyle = 'rgba(255, 182, 193, 0.5)' // 肌色の半透明

      keypoints.forEach((point, index) => {
        const x = this.mirrorX(point.x, 0)
        const y = point.y
        if (index === 0) {
          this.ctx.moveTo(x, y)
        } else {
          this.ctx.lineTo(x, y)
        }
      })
      this.ctx.closePath()
      this.ctx.fill()

      // 指の各部分を描画
      const fingers = [
        ['thumb', 'thumb_tip'],
        ['index_finger', 'index_finger_tip'],
        ['middle_finger', 'middle_finger_tip'],
        ['ring_finger', 'ring_finger_tip'],
        ['pinky', 'pinky_tip'],
      ]

      // キーポイントを肌色の線で結ぶ
      this.ctx.beginPath()
      this.ctx.strokeStyle = 'rgba(255, 182, 193, 0.5)'
      this.ctx.lineWidth = 10

      fingers.forEach((finger) => {
        const fingerPoints = keypoints.filter(
          (point) => point?.name != null && point.name.includes(finger[0]),
        )
        if (fingerPoints.length > 0) {
          this.ctx.moveTo(this.canvasElement.width - fingerPoints[0].x, fingerPoints[0].y)
          fingerPoints.forEach((point) => {
            const x = this.mirrorX(point.x, 0)
            const y = point.y
            this.ctx.lineTo(x, y)
          })
        }
      })
      this.ctx.closePath()
      this.ctx.stroke()

      // キーポイントを円で描画
      keypoints.forEach((point) => {
        const x = this.mirrorX(point.x, 0)
        const y = point.y
        // 半径2の円を描画
        this.ctx.beginPath()
        this.ctx.arc(x, y, 2, 0, Math.PI * 2, true)
        this.ctx.fillStyle = 'pink'
        this.ctx.fill()
        this.ctx.stroke()
        this.ctx.closePath()
      })

      this.ctx.restore() // 元に戻す
    })
  }

  moveText(text: string, movingDuration: number, endDuration: number, callback: () => void) {
    this.ctx.font = '30px Arial'
    const textWidth = this.ctx.measureText(text).width

    const startX = 0
    const endX = this.canvasElement.width / 2 - textWidth / 2
    const y = this.canvasElement.height / 2 - 20
    const startTime = performance.now()

    const animate = () => {
      const currentTime = performance.now()
      const elapsedTime = currentTime - startTime
      const progress = Math.min(elapsedTime / movingDuration, 1)

      // X座標の位置を更新
      const x = startX + (endX - startX) * progress

      // endDurationを超えるまでは再起処理
      if (elapsedTime < endDuration) {
        // キャンバスをクリア
        this.ctx.clearRect(0, 0, this.canvasElement.width, this.canvasElement.height)

        // テキストの背景として半透明の四角を描画
        const paddingX = 100
        const paddingY = 50

        this.ctx.fillStyle = 'rgba(255, 255, 255, 0.5)'
        this.ctx.fillRect(x - paddingX, y - paddingY, textWidth + paddingX * 2, 30 + paddingY * 2)

        // テキストを描画
        this.ctx.fillStyle = 'green'
        this.ctx.fillText(text, x, y)
        requestAnimationFrame(animate)
      } else {
        // コールバックを呼び出して終了
        callback()
      }
    }

    requestAnimationFrame(animate)
  }
}
