import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader'
import { type User } from 'type/User'
import { ThreeUtil } from 'utils/threeUtil'

import robotExpressiveGlb from '../characters/RobotExpressive.glb'

export type RobotAction =
  | 'Dance'
  | 'Death'
  | 'Idle'
  | 'Jump'
  | 'No'
  | 'Punch'
  | 'Running'
  | 'Sitting'
  | 'Standing'
  | 'ThumbsUp'
  | 'Walking'
  | 'WalkJump'
  | 'Wave'
  | 'Yes'

export class GameCharacter {
  // View関連
  characterCanvasElement: HTMLCanvasElement

  // ゲーム関連
  user: User

  // Three.js関連
  scene: THREE.Scene
  camera: THREE.PerspectiveCamera
  renderer: THREE.WebGLRenderer
  character: THREE.Group<THREE.Object3DEventMap>
  clips: THREE.AnimationClip[] = []
  mixer: THREE.AnimationMixer
  clock: THREE.Clock

  // Util関連
  threeUtil: ThreeUtil

  constructor(characterCanvasElement: HTMLCanvasElement, user: User) {
    this.characterCanvasElement = characterCanvasElement
    this.user = user

    // Three.js関連
    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(
      45,
      this.characterCanvasElement.width / this.characterCanvasElement.height,
      0.25,
      100,
    )
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.characterCanvasElement,
      alpha: true, // 背景を透明にする
    })
    this.character = new THREE.Group()
    this.mixer = new THREE.AnimationMixer(this.scene)
    this.clock = new THREE.Clock()

    this.threeUtil = new ThreeUtil()

    this.initThreeJS()
  }

  drawCharacter(): void {}

  private initThreeJS(): void {
    this.camera.position.set(-5, 3, 10)
    this.camera.lookAt(new THREE.Vector3(0, 2, 0))

    this.scene.fog = new THREE.Fog(0xe0e0e0, 20, 100)

    // lights
    const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444)
    hemiLight.position.set(0, 20, 0)
    this.scene.add(hemiLight)

    const dirLight = new THREE.DirectionalLight(0xffffff)
    dirLight.position.set(0, 20, 10)
    this.scene.add(dirLight)

    // model
    const loader = new GLTFLoader()
    loader.load(
      robotExpressiveGlb,
      (gltf) => {
        // console.log('gltf', gltf)
        this.character = gltf.scene

        // キャラクターのスケールを更新
        this.character.scale.set(0.9, 0.9, 0.9)

        this.scene.add(this.character)

        this.mixer = new THREE.AnimationMixer(this.character)
        this.clips = gltf.animations

        // 初回アニメーションの設定
        this.playLoopAction('Wave')
      },
      undefined,
      function (e) {
        console.error(e)
      },
    )

    // アニメーションループの開始
    this.animate()
  }

  animate = () => {
    const deltaTime = this.clock.getDelta() // 前回のフレームからの経過時間を取得
    this.mixer.update(deltaTime)
    this.renderer.render(this.scene, this.camera)
    requestAnimationFrame(this.animate)
  }

  moveUserArea(): void {
    this.showCharacter()

    // キャラクターのスケールを更新
    this.character.scale.set(0.3, 0.3, 0.3)

    // キャラクターの位置を更新
    const worldPosition = this.threeUtil.screenToWorld(
      70,
      this.characterCanvasElement.height - 30,
      this.characterCanvasElement,
      this.camera,
    )
    this.character.position.set(worldPosition.x, worldPosition.y, worldPosition.z)
  }

  playOneTimeAction(action: RobotAction): void {
    if (this.mixer == null) return

    this.showCharacter()
    this.mixer.stopAllAction()

    const clip = THREE.AnimationClip.findByName(this.clips, action)
    const newAction = this.mixer.clipAction(clip)
    newAction.loop = THREE.LoopOnce
    newAction.clampWhenFinished = true // アニメーション終了時にそのままの状態にする
    newAction.play()
  }

  playLoopAction(action: RobotAction): void {
    if (this.mixer == null) return

    this.showCharacter()
    this.mixer.stopAllAction()

    const clip = THREE.AnimationClip.findByName(this.clips, action)
    const newAction = this.mixer.clipAction(clip)
    newAction.loop = THREE.LoopRepeat
    newAction.play()
  }

  playActions(actions: RobotAction[]) {
    let currentActionIndex = 0

    this.showCharacter()
    this.mixer.stopAllAction()

    const playNextAction = () => {
      if (currentActionIndex < actions.length) {
        const actionName = actions[currentActionIndex]
        const clip = THREE.AnimationClip.findByName(this.clips, actionName)
        const action = this.mixer.clipAction(clip)
        action.setLoop(THREE.LoopOnce, 1)
        action.clampWhenFinished = true
        action.play()

        this.mixer.addEventListener('finished', () => {
          currentActionIndex++
          playNextAction()
        })
      }
    }

    playNextAction()
  }

  stopAction(): void {
    if (this.mixer == null) return
    this.mixer.stopAllAction()
  }

  hideCharacter() {
    this.character.visible = false
  }

  showCharacter() {
    this.character.visible = true
  }
}
