import { Enemy, MAX_ENEMY_SIZE } from 'type/Enemy'

export class GameStage {
  ctx: CanvasRenderingContext2D
  canvasElement: HTMLCanvasElement
  enemyList: Enemy[] = []

  constructor(ctx: CanvasRenderingContext2D, canvasElement: HTMLCanvasElement, enemyList: Enemy[]) {
    this.ctx = ctx
    this.canvasElement = canvasElement
    this.enemyList = enemyList
  }

  get centerX(): number {
    return this.canvasElement.width / 2
  }

  get centerY(): number {
    return this.canvasElement.height / 2
  }

  createEnemy(gameLevel: number, gameStage: number): void {
    switch (gameLevel) {
      case 1:
        this.createEnemyLevel1(gameStage)
        break
      case 2:
        this.createEnemyLevel2(gameStage)
        break
      default:
        this.createRandomOneEnemy()
        break
    }
  }

  createEnemyLevel1(gameStage: number): void {
    switch (gameStage) {
      case 1:
        this.createStaticNormalEnemy(this.centerX - 100, this.centerY - 50, 70)
        this.createStaticNormalEnemy(this.centerX + 100, this.centerY - 50, 70)
        break
      case 2:
        this.createStaticNormalEnemy(this.centerX, this.centerY - 100, 70)
        this.createStaticNormalEnemy(this.centerX, this.centerY + 50, 70)
        break
      case 3:
        this.createStaticNormalEnemy(this.centerX, this.centerY - 30, 90)
        this.createStaticNormalEnemy(this.centerX, this.centerY - 60, 65)
        this.createStaticNormalEnemy(this.centerX, this.centerY - 90, 40)
        break
      case 4:
        this.createStaticNormalEnemy(this.centerX - 100, this.centerY - 70, 90)
        this.createStaticNormalEnemy(this.centerX, this.centerY - 20, 70)
        this.createStaticNormalEnemy(this.centerX + 100, this.centerY + 30, 80)
        break
      case 5:
        this.createStaticNormalEnemy(this.centerX - 100, this.centerY - 70, 90)
        this.createStaticNormalEnemy(this.centerX, this.centerY - 20, 70)
        this.createStaticNormalEnemy(this.centerX + 100, this.centerY + 30, 80)
        this.createStaticNormalEnemy(this.centerX - 50, this.centerY - 100, 70)
        this.createStaticNormalEnemy(this.centerX + 50, this.centerY - 100, 70)
        break
      case 6:
        this.createActiveNormalEnemy(this.centerX - 90, this.centerY - 90, 70, 'x')
        this.createActiveNormalEnemy(this.centerX + 20, this.centerY + 50, 70, 'x')
        break
      case 7:
        this.createActiveNormalEnemy(this.centerX - 120, this.centerY - 40, 70, 'y')
        this.createActiveNormalEnemy(this.centerX + 30, this.centerY, 40, 'y')
        break
      case 8:
        this.createActiveNormalEnemy(this.centerX - 50, this.centerY - 40, 70, 'x')
        this.createActiveNormalEnemy(this.centerX + 20, this.centerY, 70, 'x')
        this.createActiveNormalEnemy(this.centerX - 50, this.centerY - 40, 70, 'y')
        this.createActiveNormalEnemy(this.centerX + 20, this.centerY, 70, 'y')
        this.createActiveNormalEnemy(this.centerX, this.centerY, 80, 'xy')
        break
      case 9:
        this.enemyList.push(
          new Enemy(
            'bigBoss',
            'sphere',
            'darkGreen',
            this.centerX,
            this.centerY,
            100,
            40,
            40,
            0,
            0,
            0.2,
            0,
            3,
            16,
          ),
        )
        break
      default:
        break
    }
  }

  createEnemyLevel2(gameStage: number): void {
    switch (gameStage) {
      case 1:
        this.createStaticNormalEnemy(this.centerX - 100, this.centerY - 50, 70)
        this.createStaticNormalEnemy(this.centerX + 20, this.centerY - 100, 80)
        this.createActiveNormalEnemy(this.centerX + 150, this.centerY + 20, 90, 'x')
        this.createActiveNormalEnemy(this.centerX - 130, this.centerY, 90, 'x')
        this.createActiveNormalEnemy(this.centerX + 10, this.centerY - 30, 80, 'y')
        break
      case 2:
        this.createStaticNormalEnemy(this.centerX - 100, this.centerY - 50, 70)
        this.createStaticNormalEnemy(this.centerX + 20, this.centerY - 100, 80)
        this.createActiveNormalEnemy(this.centerX + 150, this.centerY + 20, 90, 'x')
        break
      case 3:
        this.createBoxAceEnemy(this.centerX, this.centerY, 70)
        break
      case 4:
        this.createBoxAceEnemy(this.centerX - 30, this.centerY - 30, 80)
        this.createStaticNormalEnemy(this.centerX - 70, this.centerY - 70, 60)
        this.createStaticNormalEnemy(this.centerX - 10, this.centerY - 70, 60)
        this.createStaticNormalEnemy(this.centerX - 70, this.centerY - 10, 60)
        this.createStaticNormalEnemy(this.centerX - 10, this.centerY - 10, 60)
        break
      case 5:
        this.createBoxAceEnemy(this.centerX - 100, this.centerY - 100, 80)
        this.createActiveNormalEnemy(this.centerX - 60, this.centerY - 60, 70, 'xy')
        this.createActiveNormalEnemy(this.centerX - 20, this.centerY - 20, 80, 'y')
        this.createActiveNormalEnemy(this.centerX + 20, this.centerY + 20, 70, 'xy')
        this.createActiveNormalEnemy(this.centerX + 60, this.centerY + 60, 90, 'x')
        break
      case 6:
        this.createBoxAceEnemy(this.centerX - 100, this.centerY - 100, 100)
        this.createBoxAceEnemy(this.centerX + 100, this.centerY - 100, 100)
        break
      case 7:
        this.createBoxAceEnemy(this.centerX - 100, this.centerY - 100, 70)
        this.createActiveNormalEnemy(this.centerX - 100, this.centerY - 100, 80, 'xy')
        this.createActiveNormalEnemy(this.centerX - 80, this.centerY + 20, 70, 'xy')
        this.createActiveNormalEnemy(this.centerX + 40, this.centerY + 50, 80, 'xy')
        this.createActiveNormalEnemy(this.centerX, this.centerY - 60, 70, 'xy')
        break
      case 8:
        this.createBoxAceEnemy(this.centerX, this.centerY - 50, 70)
        this.createBoxAceEnemy(this.centerX + 100, this.centerY + 80, 100)
        this.createBoxAceEnemy(this.centerX - 100, this.centerY + 80, 100)
        break
      case 9:
        this.enemyList.push(
          new Enemy(
            'bigBoss',
            'icosahedron',
            'purple',
            this.centerX - 50,
            this.centerY - 50,
            100,
            50,
            50,
            2,
            1,
            0.2,
            100,
            3,
            16,
          ),
        )
        break
      default:
        break
    }
  }

  createStaticNormalEnemy(x: number, y: number, z: number): void {
    this.enemyList.push(new Enemy('normal', 'box', 'zaku', x, y, z, 30, 30, 0, 0, 0.1, 0, 1, 3))
  }

  createActiveNormalEnemy(x: number, y: number, z: number, direction: 'x' | 'y' | 'xy'): void {
    if (direction === 'x') {
      this.enemyList.push(new Enemy('normal', 'box', 'gufu', x, y, z, 30, 30, 1, 0, 0.1, 100, 1, 3))
    } else if (direction === 'y') {
      this.enemyList.push(new Enemy('normal', 'box', 'gufu', x, y, z, 30, 30, 0, 1, 0.1, 100, 1, 3))
    } else {
      this.enemyList.push(new Enemy('normal', 'box', 'gufu', x, y, z, 30, 30, 1, 1, 0.1, 100, 1, 3))
    }
  }

  createBoxAceEnemy(x: number, y: number, z: number): void {
    this.enemyList.push(new Enemy('ace', 'box', 'shar', x, y, z, 30, 30, 3, 2, 0.1, 150, 1, 5))
  }

  createRandomOneEnemy(): void {
    // X座標はenemySize~threeCanvasElement.width - enemySize * 2の範囲でランダム
    const enemyX = Math.floor(
      Math.random() * (this.canvasElement.width - 2 * MAX_ENEMY_SIZE * 2) + MAX_ENEMY_SIZE * 2,
    )
    // Y座標はenemySize~threeCanvasElement.height - enemySize * 2の範囲でランダム
    const enemyY = Math.floor(
      Math.random() * (this.canvasElement.height - 2 * MAX_ENEMY_SIZE * 2) + MAX_ENEMY_SIZE * 2,
    )
    // Z座標は80~100の範囲でランダム
    const enemyZ = Math.floor(Math.random() * 20 + 80)
    const enemy = new Enemy(
      'normal',
      'box',
      'aqua',
      enemyX,
      enemyY,
      enemyZ,
      30,
      30,
      0,
      0,
      0.1,
      0,
      1,
      3,
    )
    this.enemyList.push(enemy)
  }
}
