import noiseImage from 'images/vanta/noise.png'
import * as THREE from 'three'
import CLOUDS2 from 'vanta/dist/vanta.clouds2.min'
import FOG from 'vanta/dist/vanta.fog.min'
import GLOBE from 'vanta/dist/vanta.globe.min'
import NET from 'vanta/dist/vanta.net.min'

export class VantaEffect {
  effectDivElement: HTMLDivElement
  vantaObject: any

  constructor(effectDivElement: HTMLDivElement) {
    this.effectDivElement = effectDivElement
  }

  createGlobeEffect() {
    if (this.vantaObject != null) return

    this.vantaObject = GLOBE({
      el: this.effectDivElement,
      THREE,
      mouseControls: false,
      touchControls: false,
      gyroControls: false,
      minHeight: this.effectDivElement.clientHeight ?? 0,
      minWidth: this.effectDivElement.clientWidth ?? 0,
      scale: 1.0,
      scaleMobile: 1.0,
      backgroundAlpha: 0,
      size: 0.4,
    })
  }

  createNetEffect() {
    if (this.vantaObject != null) return

    this.vantaObject = NET({
      el: this.effectDivElement,
      THREE,
      mouseControls: false,
      touchControls: false,
      gyroControls: false,
      minHeight: this.effectDivElement.clientHeight ?? 0,
      minWidth: this.effectDivElement.clientWidth ?? 0,
      scale: 1.0,
      scaleMobile: 1.0,
      color: 0xff3f81,
      backgroundAlpha: 0,
    })
  }

  createClouds2Effect() {
    if (this.vantaObject != null) return

    this.vantaObject = CLOUDS2({
      el: this.effectDivElement,
      THREE,
      mouseControls: false,
      touchControls: false,
      gyroControls: false,
      minHeight: this.effectDivElement.clientHeight ?? 0,
      minWidth: this.effectDivElement.clientWidth ?? 0,
      scale: 1.0,
      scaleMobile: 1.0,
      texturePath: noiseImage,
    })
  }

  createFogEffect() {
    if (this.vantaObject != null) return

    this.vantaObject = FOG({
      el: this.effectDivElement,
      THREE,
      mouseControls: false,
      touchControls: false,
      gyroControls: false,
      minHeight: this.effectDivElement.clientHeight ?? 0,
      minWidth: this.effectDivElement.clientWidth ?? 0,
      highlightColor: 0xffffff,
      midtoneColor: 0x827979,
      lowlightColor: 0x6a6875,
      baseColor: 0xe3e3e3,
      blurFactor: 0.3,
    })
  }

  destroyVantaObject() {
    if (this.vantaObject == null) return

    this.vantaObject.destroy()
    this.vantaObject = null
  }
}
