import * as tf from '@tensorflow/tfjs-core'
import dayjs from 'dayjs'

import handposeModelText from '../models/handpose-classifier-model.txt'
import handposeText from '../models/handpose-definition.txt'
import { type Handpose } from '../type/Handpose'
import { TensorflowUtil } from '../utils/tensorflowUtil'

import type * as handPoseDetection from '@tensorflow-models/hand-pose-detection'
import type * as knnClassifier from '@tensorflow-models/knn-classifier'

// Util関連
let tensorflowUtil: TensorflowUtil

let webcamElement: HTMLVideoElement | null = null
let canvasElement: HTMLCanvasElement | null = null
let ctx: CanvasRenderingContext2D | null = null
let handposeClassifier: knnClassifier.KNNClassifier
let handPoseList: Handpose[] = []

function initCamera(): void {
  webcamElement = document.getElementById('webcam') as HTMLVideoElement
}

async function initCanvas(): Promise<void> {
  const canvasWrapperElement = document.getElementById('canvas-wrapper') as HTMLDivElement
  canvasElement = document.getElementById('canvas') as HTMLCanvasElement
  ctx = canvasElement.getContext('2d')

  // Canvasの大きさをvideo要素に合わせる
  if (webcamElement) {
    canvasElement.width = webcamElement.videoWidth
    canvasElement.height = webcamElement.videoHeight
    canvasWrapperElement.style.width = `${webcamElement.videoWidth}px`
    canvasWrapperElement.style.height = `${webcamElement.videoHeight}px`
  }
}

async function loadHandposeDefinition(): Promise<void> {
  const txt = await fetch(handposeText).then((res) => res.text())
  handPoseList = JSON.parse(txt)
}

function loadHandposeModel(): void {
  // デフォルトモデルを復元
  tensorflowUtil.loadKNNModel(handposeModelText).then((model) => {
    handposeClassifier = model

    console.log('load model from default')

    // 現在のモデルを表示
    const currentModelDisplayElement = document.getElementById('current-model')
    if (currentModelDisplayElement != null) {
      currentModelDisplayElement.innerText = `デフォルトモデル`
    }
  })

  // ローカルストレージにあれば保存日時を表示
  const saveDate = localStorage.getItem('handposeClassifierSaveDate')
  const savedModelDisplayElement = document.getElementById('saved-model')
  if (savedModelDisplayElement != null) {
    savedModelDisplayElement.innerText = saveDate ? `保存日時: ${saveDate}` : '保存されたモデルなし'
  }
}

// イベントリスナーを追加する関数
async function addEventListeners(detector: handPoseDetection.HandDetector): Promise<void> {
  handPoseList.forEach((pose) => {
    const button = document.getElementById(`class-${pose.id}`)
    if (button) {
      button.addEventListener('click', async () => {
        await addExample(handposeClassifier, pose.id, detector)
      })
    }
  })

  // ［download］ボタンをクリックすると学習結果がダウンロードされる
  const downloadButton = document.getElementById('download-button')
  if (downloadButton) {
    downloadButton.addEventListener('click', () => {
      downloadModel(handposeClassifier)
    })
  }

  // ファイルをアップロードすると学習結果が復元される
  const input = document.getElementById('upload-model') as HTMLInputElement
  if (input) {
    input.addEventListener('change', async () => {
      const file = input.files?.[0]
      if (file) {
        const reader = new FileReader()

        reader.onload = async () => {
          const txt = reader.result as string
          handposeClassifier = tensorflowUtil.setupKNN()

          handposeClassifier.setClassifierDataset(
            Object.fromEntries(
              JSON.parse(txt).map(([label, data, shape]: [string, number[], number[]]) => [
                label,
                tf.tensor(data, shape),
              ]),
            ),
          )

          console.log('load model from file')

          // 現在のモデルを表示
          const currentModelDisplayElement = document.getElementById('current-model')
          if (currentModelDisplayElement != null) {
            currentModelDisplayElement.innerText = `ファイルから復元したモデル`
          }
        }

        reader.readAsText(file)
      }
    })
  }

  // ［save］ボタンをクリックすると学習結果をローカルストレージに保存する
  const saveButton = document.getElementById('save-button')
  if (saveButton) {
    saveButton.addEventListener('click', () => {
      // ローカルストレージに学習結果を保存
      saveModel(handposeClassifier)
    })
  }

  // ［restore］ボタンをクリックすると学習結果をローカルストレージから復元する
  const restoreButton = document.getElementById('restore-button')
  if (restoreButton) {
    restoreButton.addEventListener('click', () => {
      // ローカルストレージから学習結果を復元
      restoreModel()
    })
  }

  // ［clear］ボタンをクリックすると学習結果をローカルストレージから削除する
  const clearButton = document.getElementById('clear-button')
  if (clearButton) {
    clearButton.addEventListener('click', () => {
      // ローカルストレージから学習結果を削除
      localStorage.removeItem('handposeClassifier')
      localStorage.removeItem('handposeClassifierSaveDate')

      const savedModelDisplayElement = document.getElementById('saved-model')
      if (savedModelDisplayElement != null) {
        savedModelDisplayElement.innerText = '保存されたモデルなし'
      }
    })
  }
}

// ウェブカメラの映像から手を検出する関数
async function estimateHands(
  detector: handPoseDetection.HandDetector,
): Promise<handPoseDetection.Hand | undefined> {
  if (!webcamElement) return
  const hands = await detector.estimateHands(webcamElement, {
    flipHorizontal: false,
  })
  return hands[0]
}

// 手のキーポイントの3D座標（x, y, z）を取得する関数
function getHandKeypoints3D(hand?: handPoseDetection.Hand): number[][] | null {
  if (hand?.keypoints3D) {
    return hand.keypoints3D.map((point) => [point.x ?? 0, point.y ?? 0, point.z ?? 0])
  }
  return null
}

// 手のポーズを予測する関数
async function estimatePose(
  classifier: knnClassifier.KNNClassifier,
  hand: handPoseDetection.Hand | undefined,
): Promise<void> {
  if (classifier.getNumClasses() > 0) {
    const keypoints3D = hand ? getHandKeypoints3D(hand) : null // キーポイントの3D座標を取得

    // デフォルトの予測結果は「なし」とする
    let predictionText = '予測ポーズ: なし\n確率: -'

    // 手のキーポイントの3D座標が検出された場合のみ予測を更新
    if (keypoints3D) {
      const tensor = tensorflowUtil.flattenAndConvertToTensor(keypoints3D) // キーポイントの3D座標をフラット化しテンソルに変換

      // KNN分類器を使ってポーズを予測
      const result = await classifier.predictClass(tensor)

      // handposeListからidとresult.labelが一致する要素を取得
      const handpose = handPoseList.find((word) => word.id === result.label)
      if (handpose) {
        predictionText = `予測ポーズ: ${handpose.name}\n確率: ${Math.round(result.confidences[result.label] * 100)}%`
      }

      tensor.dispose()
    }

    // 予測結果を表示
    const consoleElement = document.getElementById('console')
    if (consoleElement) consoleElement.innerText = predictionText
  }

  // 次のフレームで再度処理を行う
  await tf.nextFrame()
}

// ポーズの学習を追加する関数
async function addExample(
  classifier: knnClassifier.KNNClassifier,
  handposeId: string,
  detector: handPoseDetection.HandDetector,
): Promise<void> {
  const hand = await estimateHands(detector) // 手の検出結果を取得
  const keypoints3D = getHandKeypoints3D(hand) // キーポイントの3D座標を取得

  if (keypoints3D) {
    const tensor = tensorflowUtil.flattenAndConvertToTensor(keypoints3D) // キーポイントの3D座標をフラット化しテンソルに変換

    classifier.addExample(tensor, handposeId) // KNN分類器にポーズを追加
    tensor.dispose()
  }
}

// KNNモデルをダウンロードする関数
function downloadModel(classifier: knnClassifier.KNNClassifier): void {
  // モデルのデータセットを取得し、JSON文字列に変換
  const str = JSON.stringify(
    Object.entries(classifier.getClassifierDataset()).map(([label, data]) => [
      label,
      Array.from(data.dataSync()),
      data.shape,
    ]),
  )
  const blob = new Blob([str], { type: 'text/plain' }) // JSON文字列をBlobとして作成
  const url = URL.createObjectURL(blob) // BlobからURLを作成

  // ダウンロード用のリンクを作成
  const a = document.createElement('a')
  a.href = url
  a.download = 'knn-classifier-model.txt'

  // リンクをドキュメントに追加してクリックイベントを発火
  document.body.appendChild(a)
  a.click()

  document.body.removeChild(a) // リンクをドキュメントから削除
  URL.revokeObjectURL(url) // 作成したURLを解放
}

function restoreModel(): boolean {
  const savedModel = tensorflowUtil.restoreKNNModel('handposeClassifier')
  if (!savedModel) return false

  handposeClassifier = savedModel

  console.log('load model from localStorage')

  // 現在のモデルを表示
  const currentModelDisplayElement = document.getElementById('current-model')
  if (currentModelDisplayElement != null) {
    const saveDate = localStorage.getItem('handposeClassifierSaveDate')
    currentModelDisplayElement.innerText = `ストレージから復元したモデル(${saveDate})`
  }

  return true
}

// KNNモデルをローカルストレージに保存する関数
function saveModel(classifier: knnClassifier.KNNClassifier): void {
  // モデルのデータセットを取得し、JSON文字列に変換
  const str = JSON.stringify(
    Object.entries(classifier.getClassifierDataset()).map(([label, data]) => [
      label,
      Array.from(data.dataSync()),
      data.shape,
    ]),
  )

  // ローカルストレージに保存
  localStorage.setItem('handposeClassifier', str)
  const saveDate = dayjs().format('YYYY/MM/DD HH:mm:ss')
  localStorage.setItem('handposeClassifierSaveDate', saveDate)

  // 保存日時を表示
  const savedModelDisplayElement = document.getElementById('saved-model')
  if (savedModelDisplayElement != null) {
    savedModelDisplayElement.innerText = saveDate ? `保存日時: ${saveDate}` : '保存されたモデルなし'
  }
}

// ウェブカメラの画像をCanvasに描画する関数
function drawWebCamToCanvas(): void {
  if (!ctx || !canvasElement || !webcamElement) return

  ctx.clearRect(0, 0, canvasElement.width, canvasElement.height)

  // キャンバスの水平反転を設定
  ctx.save() // 現在の状態を保存
  ctx.scale(-1, 1) // 水平反転
  ctx.translate(-canvasElement.width, 0) // 座標を移動して反転を適用

  ctx.drawImage(webcamElement, 0, 0, webcamElement.videoWidth, webcamElement.videoHeight)

  ctx.restore() // 反転を元に戻す
}

// 毎フレーム走らせる処理
async function render(detector: handPoseDetection.HandDetector): Promise<void> {
  // 手を検出する
  const hand = await estimateHands(detector)
  // 手のポーズを予測する
  await estimatePose(handposeClassifier, hand)

  drawWebCamToCanvas() // canvasにvideoを描画する

  window.requestAnimationFrame(async () => {
    await render(detector)
  })
}

// 初期化関数
export async function init(): Promise<void> {
  await loadHandposeDefinition()

  tensorflowUtil = new TensorflowUtil()

  initCamera() // カメラの初期化
  if (webcamElement) {
    await tensorflowUtil.enableCam(webcamElement) // ウェブカメラの起動
  } else {
    console.error('Webcam element not found')
  }
  const detector = await tensorflowUtil.createHandDetector() // 手検出モデルの初期化
  handposeClassifier = tensorflowUtil.setupKNN() // KNNモデルの準備

  await addEventListeners(detector) // イベントリスナーの設定
  initCanvas() // Canvasの初期化

  loadHandposeModel()

  render(detector) // 毎フレーム走らせる処理
}
