import { useEffect, useRef, useState } from 'react'

import { init } from '../controls/handPoseTraining'
import classes from '../css/Training.module.css'
import handposeText from '../models/handpose-definition.txt'

type Handpose = {
  id: string
  name: string
}

const HandposeTraining = () => {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [handposeList, setHandposeList] = useState<Handpose[]>()

  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true })
        if (videoRef.current) {
          videoRef.current.srcObject = stream
        }
        // finderCountTraining.jsのinit関数を実行
        init()
      } catch (err) {
        console.error('Error accessing the camera: ', err)
      }
    }
    startCamera()

    const fetchHandposeText = async () => {
      const response = await fetch(handposeText)
      const txt = await response.text()
      // txtをJSON変換してposeListに代入
      const poseList: Handpose[] = JSON.parse(txt)
      setHandposeList(poseList)
    }
    fetchHandposeText()
  }, [])

  const videoStyles: React.CSSProperties = {
    transform: 'scaleX(-1)',
  }

  return (
    <div className={classes.wrapper}>
      <div className={classes['top-section']}>
        <div className={classes['video-wrapper']}>
          <p id="console">
            予測ポーズ: なし
            <br />
            確率: -
          </p>
          <video
            width="640"
            height="480"
            id="webcam"
            style={videoStyles}
            autoPlay
            muted
            playsInline
            className={classes.webcam}
          ></video>
          <div id="canvas-wrapper" className={classes['canvas-wrapper']}>
            <canvas id="canvas" className={classes.canvas}></canvas>
            <canvas id="smoke-canvas" className={classes['overlay-canvas']}></canvas>
          </div>
          <div style={{ marginTop: '20px' }}>
            <div style={{ marginTop: '20px' }}>
              現在トレーニング中のモデル：
              <span id="current-model" style={{ color: 'red' }}></span>
            </div>
            <div style={{ marginTop: '20px' }}>
              ローカルストレージに保存（ゲームで使用可能）
              <a href="/gesture/game">保存したモデルでゲームを開始</a>
              <br />
              <button className={`${classes['download-button']}`} id="save-button">
                save to storage
              </button>
              <span style={{ marginLeft: '10px' }} id="saved-model"></span>
            </div>
            <div style={{ marginTop: '20px' }}>
              ローカルストレージから復元（再トレーニング）
              <br />
              <button className={`${classes['download-button']}`} id="restore-button">
                restore from storage
              </button>
            </div>
            <div style={{ marginTop: '20px' }}>
              ローカルストレージをクリア
              <br />
              <button className={`${classes['download-button']}`} id="clear-button">
                clear storage
              </button>
            </div>
          </div>
        </div>
        <div>
          <div className={classes.buttons} style={{ marginTop: '40px' }}>
            {handposeList?.map((handpose) => (
              <button className={classes.button} key={handpose.id} id={`class-${handpose.id}`}>
                {handpose.name}
              </button>
            ))}
          </div>
          <div style={{ marginTop: '20px' }}>
            <div>
              ファイルダウンロード
              <br />
              <button className={`${classes['download-button']}`} id="download-button">
                file download
              </button>
            </div>
            <div style={{ marginTop: '20px' }}>ファイルから復元</div>
            <div>
              <input type="file" id="upload-model" />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default HandposeTraining
