import type * as THREE from 'three'

export type EnemyType = 'normal' | 'ace' | 'middleBoss' | 'bigBoss'

export type EnemyShape =
  | 'box'
  | 'sphere'
  | 'plane'
  | 'cone'
  | 'cylinder'
  | 'torus'
  | 'torusKnot'
  | 'octahedron'
  | 'icosahedron'

export type EnemyColor =
  | 'red'
  | 'blue'
  | 'green'
  | 'darkGreen'
  | 'yellow'
  | 'purple'
  | 'navy'
  | 'aqua'
  | 'white'
  | 'shar'
  | 'zaku'
  | 'gufu'
  | 'domu'
  | 'goggu'
  | 'zugokku'
  | 'aggai'
  | 'gerugugu'
  | 'gyan'
  | 'ziongu'

export const MAX_ENEMY_SIZE = 100

export class Enemy {
  id: number
  type: EnemyType
  shape: EnemyShape
  color: EnemyColor
  x: number
  y: number
  z: number // 0~100（0が最前面）
  originalX: number
  originalY: number
  originalZ: number
  width: number // 最大100
  height: number // 最大100
  speedX: number // 1フレームあたりのX軸の移動量
  speedY: number // 1フレームあたりのY軸の移動量
  speedZ: number // 1フレームあたりのZ軸の移動量
  moveXY: number // X軸とY軸の移動量
  power: number // プレイヤーに与えるダメージ
  stamina: number // 体力
  originalStamina: number
  threeObject?: THREE.Mesh // Three.jsの3Dオブジェクトを保持

  constructor(
    type: EnemyType,
    shape: EnemyShape,
    color: EnemyColor,
    x: number,
    y: number,
    z: number,
    width: number,
    height: number,
    speedX: number,
    speedY: number,
    speedZ: number,
    moveXY: number,
    power: number,
    stamina: number,
  ) {
    this.id = Math.floor(Math.random() * 100000000)
    this.type = type
    this.shape = shape
    this.color = color
    this.x = x
    this.y = y
    this.z = z
    this.originalX = x
    this.originalY = y
    this.originalZ = z
    if (width > MAX_ENEMY_SIZE) {
      this.width = MAX_ENEMY_SIZE
    } else {
      this.width = width
    }
    if (height > MAX_ENEMY_SIZE) {
      this.height = MAX_ENEMY_SIZE
    } else {
      this.height = height
    }
    this.speedX = speedX
    this.speedY = speedY
    this.speedZ = speedZ
    this.moveXY = moveXY
    this.power = power
    this.stamina = stamina
    this.originalStamina = stamina
  }

  static createNormalEnemy(x: number, y: number): Enemy {
    return new Enemy('normal', 'box', 'blue', x, y, 80, 30, 30, 0, 0, 0.1, 1, 0, 3)
  }

  get colorNumber(): number {
    switch (this.color) {
      case 'red':
        return 0xff0000
      case 'blue':
        return 0x0000ff
      case 'green':
        return 0x00ff00
      case 'darkGreen':
        return 0x008000
      case 'yellow':
        return 0xffff00
      case 'purple':
        return 0x800080
      case 'navy':
        return 0x000080
      case 'aqua':
        return 0x00ffff
      case 'white':
        return 0xffffff
      case 'shar':
        return 0xcc0000
      case 'zaku':
        return 0x6c8441
      case 'gufu':
        return 0x0161ad
      case 'domu':
        return 0x9179ac
      case 'goggu':
        return 0x6b4341
      case 'zugokku':
        return 0x71799d
      case 'aggai':
        return 0x511725
      case 'gerugugu':
        return 0x666f75
      case 'gyan':
        return 0xb7bff6
      case 'ziongu':
        return 0x53527c
    }
  }
}
