type UserType = 'normal'
type GameScene = 'start' | 'game' | 'gameOver' | 'result' | 'retry'
type GameEpisodeStatus = 'init' | 'prologue' | 'play' | 'epilogue'
type GameStageStatus = 'init' | 'ready' | 'playing' | 'win' | 'lose' | 'clear' | 'notClear'

export class User {
  gameScene: GameScene
  type: UserType
  stamina: number
  chargePower: number
  gameEpisode: number
  gameStage: number
  gameEpisodeStatus: GameEpisodeStatus
  gameStageStatus: GameStageStatus

  constructor(type: UserType) {
    this.type = type
    this.stamina = this.getMaxStamina()
    this.chargePower = 0
    this.gameScene = 'start'
    this.gameEpisodeStatus = 'init'
    this.gameEpisode = 1
    this.gameStage = 1
    this.gameStageStatus = 'init'
  }

  getEpisodeTitle() {
    switch (this.gameEpisode) {
      case 1:
        return '襲来'
      case 2:
        return '刺客'
      case 3:
        return '侵攻'
      case 4:
        return '油断'
      case 5:
        return '再起'
      case 6:
        return '決戦'
      default:
        return '秘密'
    }
  }

  getMaxStamina(): number {
    switch (this.type) {
      case 'normal':
        return 5
      default:
        return 5
    }
  }
}
