import * as THREE from 'three'
import { type Bullet } from 'type/Bullet'
import { type Enemy } from 'type/Enemy'
import { type User } from 'type/User'
import { ThreeUtil } from 'utils/threeUtil'

export class GameThreeJs {
  // View関連
  threeCanvasElement: HTMLCanvasElement

  // ゲーム関連
  user: User
  bulletList: Bullet[] = []
  enemyList: Enemy[] = []

  // Three.js関連
  scene: THREE.Scene
  camera: THREE.PerspectiveCamera
  renderer: THREE.WebGLRenderer

  // Util関連
  threeUtil: ThreeUtil

  constructor(
    threeCanvasElement: HTMLCanvasElement,
    user: User,
    bulletList: Bullet[],
    enemyList: Enemy[],
  ) {
    // View関連
    this.threeCanvasElement = threeCanvasElement

    // ゲーム関連
    this.user = user
    this.bulletList = bulletList
    this.enemyList = enemyList

    // Three.js関連
    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(
      45,
      this.threeCanvasElement.width / this.threeCanvasElement.height,
      0.1,
      1000,
    )
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.threeCanvasElement,
      alpha: true, // 背景を透明にする
    })
    this.initThreeJS()

    // Util関連
    this.threeUtil = new ThreeUtil()
  }

  drawEnemy(): void {
    this.enemyList.forEach((enemy) => {
      if (this.threeCanvasElement == null) return

      // 新規の敵
      if (enemy.threeObject == null) {
        this.drawNewEnemy(enemy)
      }

      // 既出の敵
      // X座標の移動
      enemy.x += enemy.speedX
      if (
        enemy.x <= enemy.width ||
        enemy.x >= this.threeCanvasElement.width - enemy.width ||
        enemy.x <= enemy.originalX - (enemy.moveXY + enemy.width) / 2 ||
        enemy.x >= enemy.originalX + (enemy.moveXY - enemy.width) / 2
      ) {
        enemy.speedX *= -1
      }
      // Y座標の移動
      enemy.y += enemy.speedY
      if (
        enemy.y <= enemy.height ||
        enemy.y >= this.threeCanvasElement.height - enemy.height ||
        enemy.y <= enemy.originalY - (enemy.moveXY + enemy.height) / 2 ||
        enemy.y >= enemy.originalY + (enemy.moveXY - enemy.height) / 2
      ) {
        enemy.speedY *= -1
      }
      // Z座標の移動
      const scale = 0.5 - (0.4 / 100) * enemy.z

      const worldPosition = this.threeUtil.screenToWorld(
        enemy.x,
        enemy.y,
        this.threeCanvasElement,
        this.camera,
      )
      enemy.threeObject?.position.set(worldPosition.x, worldPosition.y, worldPosition.z)

      if (enemy.threeObject) {
        enemy.threeObject.scale.x = scale
        enemy.threeObject.scale.y = scale
        enemy.threeObject.scale.z = scale
      }

      if (enemy.threeObject) {
        let color: THREE.Color | null = null
        if (enemy.stamina === 1) {
          // スタミナが1になった敵はdimgrayにする
          color = new THREE.Color(0x696969)
        } else if (enemy.stamina <= enemy.originalStamina / 3) {
          // スタミナが1/3以下になった敵はgoldにする
          color = new THREE.Color(0xffd700)
        }

        if (color != null) {
          if (enemy.threeObject.material instanceof THREE.MeshPhongMaterial) {
            enemy.threeObject.material.color = color
          }
        }
      }
    })
  }

  drawNewEnemy(enemy: Enemy): void {
    // シューティングゲームエリア内にThree.jsのオブジェクトを追加
    const geometry = this.createGeometry(enemy)
    const material = this.createMaterial(enemy)
    const enemyObject = new THREE.Mesh(geometry, material)

    // enemyCubeの位置を設定
    const worldPosition = this.threeUtil.screenToWorld(
      enemy.x,
      enemy.y,
      this.threeCanvasElement,
      this.camera,
    )
    enemyObject.position.set(worldPosition.x, worldPosition.y, worldPosition.z)

    // enemyCubeのサイズを設定
    enemyObject.scale.x = 0.1
    enemyObject.scale.y = 0.1
    enemyObject.scale.z = 0.1

    this.scene.add(enemyObject)

    // 3Dオブジェクトをenemyに設定
    enemy.threeObject = enemyObject
  }

  private createGeometry(enemy: Enemy): THREE.BufferGeometry {
    switch (enemy.shape) {
      case 'box':
        return new THREE.BoxGeometry()
      case 'sphere':
        return new THREE.SphereGeometry()
      case 'plane':
        return new THREE.PlaneGeometry()
      case 'cone':
        return new THREE.ConeGeometry()
      case 'cylinder':
        return new THREE.CylinderGeometry()
      case 'torus':
        return new THREE.TorusGeometry()
      case 'torusKnot':
        return new THREE.TorusKnotGeometry()
      case 'octahedron':
        return new THREE.OctahedronGeometry()
      case 'icosahedron':
        return new THREE.IcosahedronGeometry()
    }
  }

  private createMaterial(enemy: Enemy): THREE.Material {
    return new THREE.MeshPhongMaterial({ color: enemy.colorNumber })
  }

  // 爆発演出（終わったらSceneから削除）
  explodeEnemy(enemy: Enemy): void {
    const explosionPieces: Array<{ piece: THREE.Mesh; velocity: THREE.Vector3 }> = []
    const pieceCount = 100

    for (let i = 0; i < pieceCount; i++) {
      const piece = enemy.threeObject?.clone() as THREE.Mesh
      piece.material = this.createMaterial(enemy)

      // ランダムな方向に飛ばすための速度を設定
      const velocity = new THREE.Vector3(
        (Math.random() - 0.5) * 2,
        (Math.random() - 0.5) * 2,
        (Math.random() - 0.5) * 2,
      )

      explosionPieces.push({ piece, velocity })
      this.scene.add(piece)
    }

    const animateExplosion = () => {
      explosionPieces.forEach(({ piece, velocity }) => {
        piece.position.add(velocity)
        velocity.multiplyScalar(0.95) // 減速
      })

      this.renderer.render(this.scene, this.camera)

      if (explosionPieces.some(({ velocity }) => velocity.length() > 0.01)) {
        requestAnimationFrame(animateExplosion)
      } else {
        explosionPieces.forEach(({ piece }) => this.scene.remove(piece))
      }
    }

    // sceneから削除
    if (enemy.threeObject) {
      this.scene.remove(enemy.threeObject)
    }
    animateExplosion()
  }

  private initThreeJS() {
    this.camera.position.z = 3
    this.renderer.setSize(this.threeCanvasElement.width, this.threeCanvasElement.height)

    // ライトを置く
    const directionalLight = new THREE.DirectionalLight(0xffffff, 2)
    directionalLight.position.set(0, 0, 1)
    this.scene.add(directionalLight)

    // ポイントライトを左に置く
    const spotLightLeft = new THREE.PointLight(0xffffff, 10, 5)
    spotLightLeft.position.set(-1, 0.5, 0)
    this.scene.add(spotLightLeft)

    // ポイントライトを右に置く
    const spotLightRight = new THREE.PointLight(0xffffff, 10, 5)
    spotLightRight.position.set(1, 0.5, 0)
    this.scene.add(spotLightRight)

    // アニメーションループの開始
    this.animate()
  }

  animate = () => {
    requestAnimationFrame(this.animate)

    // 立方体の回転
    this.enemyList.forEach((enemy) => {
      if (enemy.threeObject) {
        enemy.threeObject.rotation.x += 0.01
        enemy.threeObject.rotation.y += 0.01
      }
    })

    // シーンのレンダリング
    this.renderer.render(this.scene, this.camera)
  }
}
