import * as THREE from 'three'

export class ThreeUtil {
  screenToWorld(
    screenX: number,
    screenY: number,
    canvas: HTMLCanvasElement,
    camera: THREE.Camera,
  ): THREE.Vector3 {
    const vector = new THREE.Vector3(
      (screenX / canvas.width) * 2 - 1,
      -(screenY / canvas.height) * 2 + 1,
      0.5,
    )
    vector.unproject(camera)
    const dir = vector.sub(camera.position).normalize()
    const distance = -camera.position.z / dir.z
    const pos = camera.position.clone().add(dir.multiplyScalar(distance))
    return pos
  }

  getCanvasPosition(
    object: THREE.Object3D,
    camera: THREE.Camera,
    canvas: HTMLCanvasElement,
  ): { x: number; y: number } {
    // オブジェクトのワールド座標を取得
    const vector = new THREE.Vector3()
    object.updateMatrixWorld()
    vector.setFromMatrixPosition(object.matrixWorld)

    // オブジェクトの座標をスクリーン座標に変換
    vector.project(camera)

    // スクリーン座標をキャンバス座標に変換
    const halfWidth = canvas.width / 2
    const halfHeight = canvas.height / 2

    const x = vector.x * halfWidth + halfWidth
    const y = -(vector.y * halfHeight) + halfHeight

    return { x, y }
  }

  getCanvasSize(
    object: THREE.Object3D,
    camera: THREE.Camera,
    canvas: HTMLCanvasElement,
  ): { width: number; height: number } {
    const box = new THREE.Box3().setFromObject(object)
    const size = new THREE.Vector3()
    box.getSize(size)

    const min = box.min.clone().project(camera)
    const max = box.max.clone().project(camera)

    const width = Math.abs(((min.x - max.x) * canvas.width) / 2)
    const height = Math.abs(((min.y - max.y) * canvas.height) / 2)

    return { width, height }
  }
}
