/* eslint-disable @typescript-eslint/return-await */
import * as tf from '@tensorflow/tfjs'
import * as handPoseDetection from '@tensorflow-models/hand-pose-detection'
import '@tensorflow/tfjs-backend-webgl'
import * as knnClassifier from '@tensorflow-models/knn-classifier'
import { createWorker, OEM } from 'tesseract.js'

export class TensorflowUtil {
  /**
   * ウェブカメラを有効にする関数
   * @param webcamElement {HTMLVideoElement} ウェブカメラの映像を表示するためのvideo要素
   * @param frameRate {number} フレームレートを設定する
   * @returns {Promise<tf.data.Webcam>} ウェブカメラのストリームを取得し、TensorFlow.jsのウェブカメラデータとして返す
   */
  async enableCam(webcamElement: HTMLVideoElement, frameRate: number = 30) {
    const constraints = {
      audio: false,
      video: {
        width: 640,
        height: 480,
        frameRate: { ideal: frameRate },
      },
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia(constraints)
      webcamElement.srcObject = stream

      await new Promise<void>((resolve) => {
        webcamElement.onloadedmetadata = () => {
          resolve()
        }
      })

      return await tf.data.webcam(webcamElement)
    } catch (error) {
      console.error('Error accessing webcam: ', error)
      alert('カメラのアクセスに失敗しました。カメラのアクセス権限を確認してください。')
      throw error
    }
  }

  // ウェブカメラの映像から手を検出する関数
  async estimateHands(
    detector: handPoseDetection.HandDetector,
    webcamElement: HTMLVideoElement | null,
  ): Promise<handPoseDetection.Hand[]> {
    if (!webcamElement) return []
    const hands = await detector.estimateHands(webcamElement, {
      flipHorizontal: false,
    })
    return hands
  }

  // KNNモデルを読み込む非同期関数
  async loadKNNModel(path: string): Promise<knnClassifier.KNNClassifier> {
    // モデルのテキストファイルを取得
    const txt = await fetch(path).then(async (res) => await res.text())
    const classifier = this.setupKNN() // TensorFlow.jsのKNN分類器を作成

    // テキストをJSONとして解析し、各ラベルに対応するデータと形状を取得
    // 取得したデータをテンソルに変換してKNN分類器に設定
    // https://github.com/tensorflow/tfjs/issues/633
    classifier.setClassifierDataset(
      Object.fromEntries(
        JSON.parse(txt).map(([label, data, shape]: [string, number[], number[]]) => [
          label, // ラベル（クラス名）
          tf.tensor(data, shape), // データをテンソルに変換
        ]),
      ),
    )

    return classifier
  }

  restoreKNNModel(storageKey: string): knnClassifier.KNNClassifier | undefined {
    const model = localStorage.getItem(storageKey)
    if (model == null) return undefined

    const classifier = this.setupKNN()
    classifier.setClassifierDataset(
      Object.fromEntries(
        JSON.parse(model).map(([label, data, shape]: [string, number[], number[]]) => [
          label,
          tf.tensor(data, shape),
        ]),
      ),
    )

    return classifier
  }

  // KNN分類器を準備する関数
  setupKNN(): knnClassifier.KNNClassifier {
    return knnClassifier.create()
  }

  /**
   * 手を検出するためのhand-pose-detectionモデルを初期化する関数
   * @return {Promise<handPoseDetection.HandDetector>} 初期化された手の検出器を返す
   */
  async createHandDetector(): Promise<handPoseDetection.HandDetector> {
    const model = handPoseDetection.SupportedModels.MediaPipeHands // MediaPipeHandsモデルを使用
    const detectorConfig: handPoseDetection.MediaPipeHandsMediaPipeModelConfig = {
      runtime: 'mediapipe',
      solutionPath: 'https://cdn.jsdelivr.net/npm/@mediapipe/hands', // MediaPipeHandsのソリューションパス
      modelType: 'full', // モデルタイプを設定
    }
    const detector = await handPoseDetection.createDetector(model, detectorConfig)
    return detector
  }

  /**
   * 手のキーポイントの3D座標をフラット化し、テンソルに変換する関数
   * @param keypoints3D {Array<Array<number>>} 手のキーポイントの3D座標の配列
   * @return {tf.Tensor} フラット化されたキーポイントのテンソルを返す
   */
  flattenAndConvertToTensor(keypoints3D: number[][]): tf.Tensor {
    const flattened = keypoints3D.flat()
    return tf.tensor(flattened).reshape([1, flattened.length])
  }

  /**
   * 手のキーポイントの座標をフラット化し、テンソルに変換する関数
   * @param keypointList {Array<Array<number>>} 手のキーポイントの座標の配列
   * @param maxSize {number} フラット化後の配列の最大サイズ
   * @return {tf.Tensor} フラット化されたキーポイントのテンソルを返す
   */
  flattenAndConvertToTensorMaxSize(keypointList: number[][], maxSize: number): tf.Tensor {
    keypointList = keypointList.filter((keypoint) => keypoint[0] !== 0 && keypoint[1] !== 0)

    if (keypointList.length < maxSize) {
      const roopCount = maxSize - keypointList.length
      for (let i = 0; i < roopCount; i++) {
        keypointList.push([0, 0])
      }
    }

    const flattened = keypointList.flat()
    return tf.tensor(flattened).reshape([1, flattened.length])
  }

  /**
   * 手のキーポイントの3D座標と2D座標を取得する関数
   * @param hands {handPoseDetection.Hand[]} 手の検出結果
   * @return {Array<{keypoints3D: number[][], keypoints: handPoseDetection.Keypoint[]}>} 手のキーポイントの3D座標と2D座標の配列を返す
   */
  getHandKeypoints(
    hands: handPoseDetection.Hand[],
  ): Array<{ keypoints3D: number[][]; keypoints: handPoseDetection.Keypoint[] }> {
    return hands.map((hand) => {
      const keypoints3D = hand.keypoints3D
        ? hand.keypoints3D
            .map((point) => [point.x, point.y, point.z])
            .filter((point): point is [number, number, number] =>
              point.every((coord) => coord !== undefined),
            )
        : []

      return { keypoints3D, keypoints: hand.keypoints }
    })
  }

  /**
   * テキストを画像から読み取る関数
   * @param canvas
   * @returns
   */
  async evaluateTextImage(canvas: OffscreenCanvas): Promise<[string, ImageData | undefined]> {
    const worker = await createWorker('eng', OEM.TESSERACT_LSTM_COMBINED, {
      logger: (m) => {
        console.log(m)
      },
    })

    await worker.setParameters({
      tessedit_char_whitelist: '123456789', // 数字のみ読み取る
    })

    const {
      data: { text, blocks },
    } = await worker.recognize(canvas)

    await worker.terminate()

    // 認識したテキストを取得する
    let evaluatedText = ''
    if (text.length > 0) {
      // 1文字目だけを返す
      evaluatedText = text[0]
    } else {
      evaluatedText = '?'
    }

    const offscreenCtx = canvas.getContext('2d') as OffscreenCanvasRenderingContext2D
    if (offscreenCtx === null) {
      throw new Error('2D context not found on canvas')
    }

    // 認識したテキストのだけのイメージを取得する
    let imageData
    if (blocks != null && blocks.length > 0) {
      // 最初のテキスト領域を使用
      // ログも出力
      const {
        bbox: { x0, y0, x1, y1 },
      } = blocks[0]
      const width = x1 - x0
      const height = y1 - y0

      imageData = offscreenCtx.getImageData(x0, y0, width, height)
    }
    return [evaluatedText, imageData]
  }

  /**
   * 画像をダウンロードする関数
   * @param imageData
   * @returns
   */
  saveImageDownload(imageData: ImageData | undefined): void {
    if (imageData == null) return
    const canvas = document.createElement('canvas')
    canvas.width = imageData.width
    canvas.height = imageData.height
    const ctx = canvas.getContext('2d') as CanvasRenderingContext2D
    ctx.putImageData(imageData, 0, 0)
    const url = canvas.toDataURL('image/png')
    const a = document.createElement('a')
    a.href = url
    a.download = 'image.png'
    a.click()
  }
}
