async function loadHandposeDefinition(): Promise<void> {
  const txt = await fetch(handposeText).then(async (res) => await res.text())
  handPoseDefinitions = JSON.parse(txt)
}

// 手のポーズを予測する関数
async function estimateHandpose(
  allHandKeypoints: Array<{ keypoints3D: number[][]; keypoints: handPoseDetection.Keypoint[] }>,
): Promise<KnnEstimated[]> {
  return await Promise.all(
    allHandKeypoints.map(async (keypoints, index) => {
      const tensor = tensorflowUtil.flattenAndConvertToTensor(keypoints.keypoints3D) // キーポイントの3D座標をフラット化しテンソルに変換

      // KNN分類器を使ってポーズを予測
      const hand = await handposeClassifier.predictClass(tensor)

      const handposeId = hand.label
      const handposeName = handPoseDefinitions.find((pose) => pose.id === handposeId)?.name
      const probabilities = hand.confidences // 各ポーズの確率を取得

      tensor.dispose()

      return {
        id: handposeId,
        name: handposeName ?? '',
        probability: probabilities[hand.label],
        keypoints: keypoints.keypoints,
      }
    }),
  )
}

function setBullet(hands: handPoseDetection.Hand[], poses: KnnEstimated[]): void {
  hands.forEach((hand, index) => {
    const { id, probability } = poses[index]
    // 手のポーズがgun_shotの場合
    if (id === 'gun_shot' && probability === 1) {
      const recentlyHandpose = handposeHistory.slice(-10)

      // chargePowerがあればチャージショットと判定
      if (user.chargePower > 0) {
        setBeamBullet(hand)
        // 直近10フレーム分のhandposeHistoryにgun_reloadが含まれていれば通常ショットと判定
      } else if (recentlyHandpose.some((poses) => poses.some((pose) => pose.id === 'gun_reload'))) {
        setNormalBullet(hand)
      }

      // handposeHistoryを初期化
      handposeHistory.length = 0
      return
    }

    // 手のポーズがgun_reloadの場合
    if (id === 'gun_reload' && probability === 1) {
      // 直近30フレーム分のhandposeHistoryが全てgun_reloadであればチャージショットと判定
      const recentlyHandpose = handposeHistory.slice(-30)

      if (
        recentlyHandpose.length === 30 &&
        recentlyHandpose.every((poses) => poses.some((pose) => pose.id === 'gun_reload'))
      ) {
        setChargePower()

        // handposeHistoryを初期化
        handposeHistory.length = 0
      }
    }
  })
}

function setChargePower(): void {
  if (user.chargePower >= 5) return

  user.chargePower += 1
  playSound('powerCharge')
}

function setBeamBullet(hand: handPoseDetection.Hand): void {
  // 人差し指のkeypointの座標を取得
  const middleFingerMcp = hand.keypoints.find((keypoint) => keypoint.name === 'middle_finger_mcp')

  if (middleFingerMcp != null) {
    const bulletSize = 50 * user.chargePower
    const bullet = new Bullet(
      'beam',
      gameDraw.shootingCtxDrawUtil.mirrorX(middleFingerMcp.x, bulletSize),
      middleFingerMcp.y,
      bulletSize,
      user.chargePower,
    )

    bulletList.push(bullet)

    // 発射音を再生
    playSound('beamShot')

    // チャージショット後はchargePowerを初期化
    user.chargePower = 0
  }
}

function setNormalBullet(hand: handPoseDetection.Hand): void {
  // 人差し指のkeypointの座標を取得
  const indexFinderPip = hand.keypoints.find((keypoint) => keypoint.name === 'index_finger_pip')

  // 弾を生成
  // 但し弾は同時に1発まで
  if (indexFinderPip != null && bulletList.length === 0) {
    const bulletSize = 30
    const bullet = new Bullet(
      'normal',
      gameDraw.shootingCtxDrawUtil.mirrorX(indexFinderPip.x, bulletSize),
      indexFinderPip.y,
      30,
      1,
    )

    bulletList.push(bullet)

    // 発射音を再生
    playSound('normalShot')
  }
}

function setEnemy(): void {
  enemyList.forEach((enemy) => {
    if (!threeCanvasElement) return

    // 徐々に手前に移動
    if (enemy.z > 0) {
      enemy.z -= enemy.speedZ
    } else {
      enemy.z = 0
    }

    // 大きさを更新
    if (enemy.threeObject != null) {
      const realSize = gameThreeJs.threeUtil.getCanvasSize(
        enemy.threeObject,
        gameThreeJs.camera,
        threeCanvasElement,
      )
      enemy.width = realSize.width
      enemy.height = realSize.height
    }
  })
}

function setCatch(hands: handPoseDetection.Hand[], poses: KnnEstimated[]): void {
  hands.forEach((hand, index) => {
    const { id, probability } = poses[index]

    // 手のポーズがcatchの場合
    if (id === 'catch' && probability === 1) {
      const thumbTip = hand.keypoints.find((keypoint) => keypoint.name === 'thumb_tip')
      const indexFinderTip = hand.keypoints.find((keypoint) => keypoint.name === 'index_finger_tip')

      // 直近10フレーム分のhandposeHistoryが全てcatchでなければ掴まない
      const recentlyHandpose = handposeHistory.slice(-10)
      if (
        recentlyHandpose.length !== 10 ||
        !recentlyHandpose.every((poses) => poses.some((pose) => pose.id === 'catch'))
      ) {
        return
      }

      // 直近5フレームのY座標が連続して下がっていなければ掴まない
      for (let i = 0; i < 5; i++) {
        const currentPose = recentlyHandpose[recentlyHandpose.length - 1 - i]
        const prevPose = recentlyHandpose[recentlyHandpose.length - 2 - i]

        // 両手の場合は掴まない
        if (currentPose.length !== 1 || prevPose.length !== 1) return

        // 人差し指のY座標
        const currentIndexFinderTipY = currentPose[0].keypoints.find(
          (keypoint) => keypoint.name === 'index_finger_tip',
        )?.y
        const prevIndexFinderTipY = prevPose[0].keypoints.find(
          (keypoint) => keypoint.name === 'index_finger_tip',
        )?.y

        if (currentIndexFinderTipY == null || prevIndexFinderTipY == null) return

        // 現在の人差し指のY座標が前の人差し指のY座標よりも小さい場合（上がっている）は掴まない
        if (currentIndexFinderTipY <= prevIndexFinderTipY) {
          return
        }

        // 親指のY座標
        const currentThumbTipY = currentPose[0].keypoints.find(
          (keypoint) => keypoint.name === 'thumb_tip',
        )?.y
        const prevThumbTipY = prevPose[0].keypoints.find(
          (keypoint) => keypoint.name === 'thumb_tip',
        )?.y

        if (currentThumbTipY == null || prevThumbTipY == null) return

        // 現在の親指のY座標が前の親指のY座標よりも大きい場合（下がっている）は掴まない
        if (currentThumbTipY >= prevThumbTipY) {
          return
        }
      }

      console.log('catch pose!!')

      // 親指と人差し指のX座標とY座標が敵のX座標、Y座標に近づいたら敵を掴む
      enemyList.forEach((enemy) => {
        if (thumbTip == null || indexFinderTip == null) return
        if (enemy.threeObject == null || threeCanvasElement == null) return

        // 敵の座標を取得
        const enemyPosition = gameThreeJs.threeUtil.getCanvasPosition(
          enemy.threeObject,
          gameThreeJs.camera,
          threeCanvasElement,
        )

        // 敵の大きさを取得
        const enemySize = gameThreeJs.threeUtil.getCanvasSize(
          enemy.threeObject,
          gameThreeJs.camera,
          threeCanvasElement,
        )

        // X座標は反転しているので、親指のX座標を反転させる
        const thumbX = gameDraw.shootingCtxDrawUtil.mirrorX(thumbTip.x)
        const indexFinderX = gameDraw.shootingCtxDrawUtil.mirrorX(indexFinderTip.x)

        // 親指のX座標 < 敵のX座標 + 敵の幅 / 2 && 親指のX座標 > 敵のX座標 - 敵の幅 / 2
        // 人差し指のX座標 < 敵のX座標 + 敵の幅 / 2 && 人差し指のX座標 > 敵のX座標 - 敵の幅 / 2
        if (
          thumbX < enemyPosition.x + enemySize.width / 2 &&
          thumbX > enemyPosition.x - enemySize.width / 2 &&
          indexFinderX < enemyPosition.x + enemySize.width / 2 &&
          indexFinderX > enemyPosition.x - enemySize.width / 2
        ) {
          console.log('X position range')
          // 敵のY座標 + 敵の高さ / 2 < 親指のY座標
          // 敵のY座標 - 敵の高さ / 2 > 人差し指のY座標
          // 補正値を入れているのは、掴むときに少しズレるため
          if (
            enemyPosition.y + enemySize.height / 2 < thumbTip.y &&
            enemyPosition.y - enemySize.height / 2 > indexFinderTip.y
          ) {
            console.log('Catach Enemy', enemy)
            removeEnemy(enemy, true)
            playSound('explosion1')

            // handposeHistoryを初期化
            handposeHistory.length = 0
          }
        }
      })
    }
  })
}

function setGameScene(): void {
  if (user.gameScene === 'start') {
    vantaEffect.createClouds2Effect()
  }
}

function setGameEpisode(): void {
  if (user.gameScene === 'game') {
    // プロローグを表示
    if (user.gameEpisodeStatus === 'init') {
      // キャラクターを非表示にする
      gameCharacter.hideCharacter()

      // globeエフェクト
      vantaEffect.createGlobeEffect()

      // プロローグの音
      playSound('prologue')

      user.gameEpisodeStatus = 'prologue'

      // 5秒後にゲーム開始
      setTimeout(() => {
        user.gameEpisodeStatus = 'play'
      }, 5000)
    }
  }
}

function setGameStage(): void {
  switch (user.gameStageStatus) {
    case 'init':
      // 敵の新規作成
      gameStage.createEnemy(user.gameEpisode, user.gameStage)

      // 弾の初期化
      bulletList.length = 0

      // エピソードのglobeエフェクトを削除
      vantaEffect.destroyVantaObject()

      // キャラクターのアニメーション開始
      // ステージ1の場合のみ走るアクション付き
      if (user.gameStage === 1) {
        gameCharacter.playLoopAction('Walking')
        setTimeout(() => {
          gameCharacter.playLoopAction('Idle')
        }, 2000)
      } else {
        gameCharacter.playLoopAction('Idle')
      }

      setTimeout(() => {
        // このsetTimeout内の処理はready→playingに変わる時に一度だけ実行される
        user.gameStageStatus = 'playing'

        // ボス戦の場合
        if (user.gameStage === LAST_STAGE_NUMBER) {
          // ボス登場の音を再生
          playSound('bossAppearance')

          // 霧の演出
          vantaEffect.createFogEffect()
          setTimeout(() => {
            vantaEffect.destroyVantaObject()
          }, 2000)
        } else {
          // 敵出現の音を再生
          playSound('enemyAppearance1')
        }
      }, 3000)

      // ready状態に移行
      user.gameStageStatus = 'ready'
      break
    case 'ready':
      // drawStageReady()を実行する
      break
    case 'playing':
      // 敵を全滅させたらクリア
      if (enemyList.length === 0) {
        user.gameStageStatus = 'win'
      }
      break
    case 'win':
      console.log('Win!!')
      if (user.gameStage === LAST_STAGE_NUMBER) {
        setTimeout(() => {
          playSound('win')
        }, 3)
        // ラストステージであればエピローグを表示後に次のエピソードに進む
        user.gameEpisodeStatus = 'epilogue'

        // キャラクターがジャンプして喜ぶ
        gameCharacter.playLoopAction('Jump')

        // 7秒後に次のエピソードに遷移
        setTimeout(() => {
          user.gameEpisode += 1
          user.gameEpisodeStatus = 'init'
          user.gameStage = 1
          user.gameStageStatus = 'init'
        }, 7000)
      } else {
        user.gameStageStatus = 'clear'

        // キャラクターがいいねをする
        gameCharacter.playOneTimeAction('ThumbsUp')

        setTimeout(() => {
          // 次のステージに進む
          user.gameStage += 1
          user.gameStageStatus = 'init'

          // キャラクターのアニメーション変更
          gameCharacter.playLoopAction('Idle')
        }, 2000)
      }
      break
    case 'lose':
      console.log('lose!!')
      user.gameStageStatus = 'notClear'

      // 3秒後にステージ1に戻る
      setTimeout(() => {
        user.gameStage = 1
        user.gameStageStatus = 'init'
      }, 3000)
      break
    case 'clear':
      // drawStageClear()を実行する
      break
    case 'notClear':
      // drawStageNotClear()を実行する
      break
  }
}

function judgeHit(): void {
  // 弾と敵の当たり判定
  bulletList.forEach((bullet, bulletIndex) => {
    // console.log('bullet', bullet)
    enemyList.forEach((enemy, enemyIndex) => {
      // console.log('enemy', enemy)
      if (enemy.threeObject == null || !threeCanvasElement) return

      // 既に当たった敵には当たり判定しない
      if (bullet.hitEnemyIds.includes(enemy.id)) return

      // canvasSizeを使って弾と敵の座標が重なったら当たり判定

      // ビームの場合は当たり判定を広げる
      let power = 0
      if (bullet.type === 'beam') {
        power = bullet.power * 5
      }

      if (
        bullet.x > enemy.x - enemy.width + 20 - power / 2 &&
        bullet.x < enemy.x + enemy.width - 20 + power / 2 &&
        bullet.y > enemy.y - enemy.height + 20 - power / 2 &&
        bullet.y < enemy.y + enemy.height - 20 + power / 2 &&
        bullet.z > 20 && // 近すぎる場合は当たり判定しない
        bullet.z > enemy.z
      ) {
        // 弾を削除
        if (bullet.type === 'normal') {
          bulletList.splice(bulletIndex, 1)
        }

        // 敵のスタミナを減らす
        if (enemy.stamina > 0) {
          playSound('hit')
          enemy.stamina -= bullet.power
          bullet.hitEnemyIds.push(enemy.id)
        }

        if (enemy.stamina <= 0) {
          // 爆発演出後に敵を削除
          removeEnemy(enemy, true)
          playSound('explosion1')
        }
      }
    })
  })
}

function judgeDamage() {
  // 近づかれたらダメージを受ける
  enemyList.forEach((enemy) => {
    if (enemy.z <= 0) {
      if (enemy.type === 'middleBoss' || enemy.type === 'bigBoss') {
        // ボスに負けたらステージ1に戻る
        user.gameStageStatus = 'lose'
        playSound('lose')
      }

      // 敵を削除
      removeEnemy(enemy, false)
      playSound('damage')

      // スタミナを減らす
      user.stamina -= enemy.power

      // スタミナが0以下になったらゲームオーバー
      if (user.stamina <= 0) {
        // キャラクターのアニメーション変更
        gameCharacter.playOneTimeAction('Death')

        user.gameScene = 'gameOver'
        playSound('gameOver')
        return
      }

      // キャラクターのアニメーション変更
      gameCharacter.playOneTimeAction('No')
    }
  })
}

function removeEnemy(enemy: Enemy, isExplosion: boolean): void {
  console.log('removeEnemy', enemy)
  // enemyListから削除
  const enemyIndex = enemyList.indexOf(enemy)
  enemyList.splice(enemyIndex, 1)

  if (enemy.threeObject != null) {
    if (isExplosion) {
      // 爆発演出
      gameThreeJs.explodeEnemy(enemy)
    } else {
      // sceneから削除
      gameThreeJs.scene.remove(enemy.threeObject)
    }
  }
}

function initUser() {
  user = new User('normal')
  const debugEpisode = process.env.REACT_APP_DEBUG_EPISODE
  if (debugEpisode != null) {
    user.gameEpisode = parseInt(debugEpisode)
  }

  const debugStage = process.env.REACT_APP_DEBUG_STAGE
  if (debugStage != null) {
    user.gameStage = parseInt(debugStage)
  }
}

function startGame() {
  user.gameScene = 'game'

  // キャラクターの位置を移動させる
  gameCharacter.moveUserArea()

  // スタート画面のclouds2エフェクトを削除
  vantaEffect.destroyVantaObject()
}

function draw(hands: handPoseDetection.Hand[], poses: KnnEstimated[]) {
  gameDraw.drawInit()
  gameDraw.shootingCtxDrawUtil.drawOnlyHandToCanvas(hands)
  gameDraw.shootingCtxDrawUtil.drawPoseNameToCanvas(hands, poses)

  if (user.gameScene === 'start') {
    gameDraw.drawGameStart(() => {
      startGame()
    })
    return
  }

  if (user.gameScene === 'gameOver') {
    gameDraw.drawGameOver()
    return
  }

  if (user.gameScene === 'result') {
    gameDraw.drawGameResult()
    return
  }

  if (user.gameEpisodeStatus !== 'play') {
    // プロローグを表示
    if (user.gameEpisodeStatus === 'prologue') {
      gameDraw.drawPrologue()
      return
    }

    // エピローグを表示
    if (user.gameEpisodeStatus === 'epilogue') {
      gameDraw.drawEpilogue()
    }
    return
  }

  gameDraw.drawUser()

  if (user.gameStageStatus !== 'playing') {
    if (user.gameStageStatus === 'ready') {
      gameDraw.drawStageReady()
    } else if (user.gameStageStatus === 'clear') {
      gameDraw.drawStageClear()
    } else if (user.gameStageStatus === 'notClear') {
      gameDraw.drawStageNotClear()
    }
    return
  }

  gameDraw.drawInitPlaying()
  gameThreeJs.drawEnemy()
  gameCharacter.drawCharacter()
  gameDraw.drawEffect()
  gameDraw.drawDistanceText()
  gameDraw.drawWarningText()
  gameDraw.drawBallet()
}

// 毎フレーム走らせる処理
async function render(detector: handPoseDetection.HandDetector) {
  console.log(
    `gameScene: ${user.gameScene}, gameEpisodeStatus: ${user.gameEpisodeStatus}, gameStageStatus: ${user.gameStageStatus}`,
  )
  // 手を検出する（配列には片手の場合は１つ、両手の場合は2つが入る）
  // [{ keypoints, keypoints3D, score, handedness }]
  const hands = await tensorflowUtil.estimateHands(detector, webcamElement)

  // 手のキーポイントの3D座標を取得する
  const allHandKeypoints = tensorflowUtil.getHandKeypoints(hands)

  // 手のポーズを予測する（配列には片手の場合は１つ、両手の場合は2つが入る）
  // [{ id, name, probability }]
  const poses = await estimateHandpose(allHandKeypoints)

  // ゲームのシーンをコントロールする
  setGameScene()

  // エピソードをコントロールする
  setGameEpisode()

  if (user.gameScene === 'game' && user.gameEpisodeStatus === 'play') {
    // ステージのステータスをコントロールする
    setGameStage()

    if (user.gameStageStatus === 'playing') {
      saveHandpose(poses)
      setEnemy()
      setBullet(hands, poses)
      setCatch(hands, poses)
    }
  }

  draw(hands, poses)

  if (
    (user.gameScene === 'game' && user.gameEpisodeStatus === 'play') ||
    user.gameStageStatus === 'playing'
  ) {
    judgeDamage()
    judgeHit()
  }

  window.requestAnimationFrame(async () => {
    await render(detector)
  })
}

// 初期化関数
export async function init() {
  await loadHandposeDefinition() // ポーズの定義を読み込む

  tensorflowUtil = new TensorflowUtil()

  initCamera() // カメラの初期化
  if (webcamElement) {
    await tensorflowUtil.enableCam(webcamElement) // ウェブカメラの起動
  } else {
    throw new Error('Webcam element not found')
  }
  const detector = await tensorflowUtil.createHandDetector() // 手検出モデルの初期化

  const savedHandpose = tensorflowUtil.restoreKNNModel('handposeClassifier') // KNNモデルを復元
  if (savedHandpose != null) {
    handposeClassifier = savedHandpose
  } else {
    // ローカルストレージに保存されていなければデフォルトのモデルを読み込む
    handposeClassifier = await tensorflowUtil.loadKNNModel(handposeModelText) // KNNモデルを読み込む
  }

  initCanvas() // Canvasの初期化

  if (
    !shootingCtx ||
    !shootingCanvasElement ||
    !ctx ||
    !canvasElement ||
    !threeCanvasElement ||
    !characterCanvasElement ||
    !effectDivElement
  )
    return

  initUser()

  gameStage = new GameStage(ctx, canvasElement, enemyList)
  gameDraw = new GameDraw(
    webcamElement,
    canvasElement,
    shootingCanvasElement,
    ctx,
    shootingCtx,
    effectDivElement,
    user,
    bulletList,
    enemyList,
  )
  gameThreeJs = new GameThreeJs(threeCanvasElement, user, bulletList, enemyList)
  gameCharacter = new GameCharacter(characterCanvasElement, user)
  vantaEffect = new VantaEffect(effectDivElement)

  gameDraw.initStars()

  render(detector) // 毎フレーム走らせる処理
}

function saveHandpose(poses: KnnEstimated[]): void {
  // 30フレーム分をhandposeHistoryに保持する
  handposeHistory.push(poses)
  if (handposeHistory.length > 30) {
    handposeHistory.shift()
  }
}
