export type BulletType = 'normal' | 'beam'

export class Bullet {
  type: BulletType
  x: number
  y: number
  z: number // 0~100（0が最前面）
  originalX: number
  originalY: number
  originalZ: number
  size: number // 弾の大きさ
  originalSize: number
  speed: number // 1フレームあたりのZ軸の移動量
  power: number // プレイヤーに与えるダメージ
  hitEnemyIds: number[] = [] // 当たった敵のIDリスト

  constructor(type: BulletType, x: number, y: number, size: number, power: number) {
    this.type = type
    this.x = x
    this.y = y
    this.z = 0
    this.originalX = x
    this.originalY = y
    this.originalZ = 0
    this.size = size
    this.originalSize = size
    this.speed = this.getSpeed()
    this.power = power
  }

  getSpeed(): number {
    switch (this.type) {
      case 'normal':
        return 4
      case 'beam':
        return 3
    }
  }
}
