import { useEffect, useRef } from 'react'

import { FRAME_RATE, init } from '../controls/game'
import classes from '../css/GestureGame.module.css'

const GestureGame = () => {
  const videoRef = useRef<HTMLVideoElement>(null)

  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            frameRate: { ideal: FRAME_RATE, max: FRAME_RATE }, // フレームレートの設定
          },
        })
        if (videoRef.current) {
          videoRef.current.srcObject = stream
        }
        // game.jsのinit関数を実行
        init()
      } catch (err) {
        console.error('Error accessing the camera: ', err)
      }
    }

    startCamera()
  }, [])

  return (
    <div className={classes.wrapper}>
      <div id="app">
        <div className={classes['logo-wrapper']}></div>
        <video
          width="640"
          height="480"
          id="webcam"
          autoPlay
          muted
          playsInline
          className={classes.webcam}
        ></video>
        <div id="canvas-wrapper" className={classes['canvas-wrapper']}>
          <canvas id="canvas" className={classes.canvas}></canvas>
          <div id="effect-div" className={classes['overlay-canvas']}></div>
          <canvas id="three-canvas" className={classes['overlay-canvas']}></canvas>
          <canvas id="character-canvas" className={classes['overlay-canvas']}></canvas>
          <canvas id="shooting-canvas" className={classes['overlay-canvas']}></canvas>
        </div>
      </div>
    </div>
  )
}

export default GestureGame
