import beamShotSound from '../sounds/beam-shot.mp3'
import bossAppearanceSound from '../sounds/boss-appearance.mp3'
import damageSound from '../sounds/damage.mp3'
import dangerSound from '../sounds/danger.mp3'
import enemyAppearance1Souncd from '../sounds/enemy-appearance1.mp3'
import explosion1 from '../sounds/explosion1.mp3'
import gameOverSound from '../sounds/game-over.mp3'
import hitSound from '../sounds/hit.mp3'
import loseSound from '../sounds/lose.mp3'
import normalShotSound from '../sounds/normal-shot.mp3'
import powerChargeSound from '../sounds/power-charge.mp3'
import prologueSound from '../sounds/prologue.mp3'
import warningSound from '../sounds/warning.mp3'
import winSound from '../sounds/win.mp3'

export function playSound(fileName: string, isFadeout = false): void {
  let sound: HTMLAudioElement

  switch (fileName) {
    case 'normalShot':
      sound = new Audio(normalShotSound)
      break
    case 'beamShot':
      sound = new Audio(beamShotSound)
      break
    case 'powerCharge':
      sound = new Audio(powerChargeSound)
      break
    case 'hit':
      sound = new Audio(hitSound)
      break
    case 'explosion1':
      sound = new Audio(explosion1)
      break
    case 'warning':
      sound = new Audio(warningSound)
      break
    case 'danger':
      sound = new Audio(dangerSound)
      break
    case 'enemyAppearance1':
      sound = new Audio(enemyAppearance1Souncd)
      break
    case 'bossAppearance':
      sound = new Audio(bossAppearanceSound)
      break
    case 'damage':
      sound = new Audio(damageSound)
      break
    case 'prologue':
      sound = new Audio(prologueSound)
      break
    case 'win':
      sound = new Audio(winSound)
      break
    case 'lose':
      sound = new Audio(loseSound)
      break
    case 'gameOver':
      sound = new Audio(gameOverSound)
      break
    default:
      return
  }
  sound.currentTime = 0 // 再生位置をリセット
  sound.volume = 1
  sound.play()

  if (isFadeout) {
    fadeOutAudio(sound, 3)
  }
}

function fadeOutAudio(sound: HTMLAudioElement, duration: number) {
  const step = 0.01 // 音量を減少させるステップ
  const interval = (duration * 1000) / (1 / step) // インターバルの計算
  const fadeOutInterval = setInterval(() => {
    if (sound.volume > step) {
      sound.volume -= step
    } else {
      sound.volume = 0
      clearInterval(fadeOutInterval)
    }
  }, interval)
}
